(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-987":{scenario:{company:"Lam Hồng Air",supervisor:{name:"Hoàng Mai Anh",role:{vi:"Tiếp viên trưởng",en:"Cabin Manager (Purser)"}},ref_code:"PIL-0417",title:{vi:"Đúng mã dịch vụ. Đúng số khách. An toàn trước tiên.",en:"Right service code. Right headcount. Safety first."},brief:{vi:"Chuyến bay 417 chuẩn bị đóng cửa. Danh sách đặt chỗ có 172 khách người lớn, 10 trẻ em và 4 em bé bế trên tay; 3 khách người lớn không có mặt đã được hạ tải. Khách ghế 3A không tự di chuyển được, phải nâng từ xe lăn vào tận ghế. Bản nháp danh sách PIL-0417 ghi mã SSR WCHR và tổng khách trên tàu 179. Đối chiếu danh sách khách đã duyệt, sửa hai trường và lập báo cáo bàn giao cho tiếp viên trưởng.",en:"Flight 417 is about to close its doors. The booking list shows 172 adults, 10 children and 4 lap infants; 3 adult no-shows have been offloaded. The passenger in seat 3A cannot move unaided and must be lifted from the wheelchair into the seat. Draft passenger list PIL-0417 shows SSR code WCHR and 179 passengers on board. Compare it with the approved passenger list, correct both fields and write a handover report for the purser."},reference_title:{vi:"Danh sách hành khách & loadsheet đã duyệt · PIL-0417",en:"Approved passenger list & loadsheet · PIL-0417"},fields:[{id:"SSR_CODE",label:{vi:"Mã dịch vụ đặc biệt ghế 3A",en:"Special service code, seat 3A"},initial:"WCHR",expected:"WCHC",choices:["WCHR","WCHS","WCHC"],reference:"Danh sách khách đặc biệt (SSR)",hint:{vi:"WCHR dành cho khách tự lên xuống bậc và đi lại trong khoang được; khách phải nâng vào ghế cần mức hỗ trợ cao nhất.",en:"WCHR is for passengers who can climb steps and walk in the cabin; a passenger lifted into the seat needs the highest level of help."}},{id:"PAX_TOTAL",label:{vi:"Tổng số hành khách trên tàu",en:"Total passengers on board"},initial:"179",expected:"183",reference:"Bảng cân bằng tải (loadsheet)",ref_value:{vi:"Đặt chỗ: 172 người lớn, 10 trẻ em, 4 em bé bế tay; 3 người lớn không có mặt đã hạ tải",en:"Booked: 172 adults, 10 children, 4 lap infants; 3 adult no-shows offloaded"},hint:{vi:"Em bé bế trên tay không chiếm ghế nhưng vẫn là người trên tàu và phải có trong số đếm.",en:"Lap infants take no seat but are still on board and must be counted."}}],sop32:{vi:"Tổng hành khách trên tàu = người lớn đã lên tàu + trẻ em + em bé bế tay, sau khi trừ khách không có mặt đã hạ tải; số đếm thực tế phải khớp loadsheet trước khi đóng cửa.",en:"Total passengers on board = adults boarded + children + lap infants, after removing offloaded no-shows; the physical headcount must match the loadsheet before door closure."},context:{label:"PIL / FLT 417",metrics:[{label:{vi:"Ghế đã bán",en:"Seats sold"},value:"182"},{label:{vi:"Em bé bế tay (INF)",en:"Lap infants (INF)"},value:"4"},{label:{vi:"Khách không có mặt",en:"No-shows"},value:"3"}]},crisis:{vi:"Một khách hạng thẻ vàng bế con 10 tháng tuổi đòi ngồi ghế 14C ở hàng cửa thoát hiểm cho rộng chân, dọa khiếu nại. Nhân viên mặt đất nói: “Chuyến ngắn thôi, cho anh ấy ngồi đi cho êm, kẻo trễ giờ đóng cửa.”",en:"A gold-tier passenger holding a 10-month-old demands seat 14C in the exit row for legroom and threatens to complain. The gate agent says: “It's a short flight, just let him sit there so we don't delay the door.”"},options:{safe:{vi:"Lịch sự từ chối vì khách bế em bé không được ngồi hàng cửa thoát hiểm, giải thích lý do an toàn, đề xuất ghế rộng khác ngoài hàng thoát hiểm và báo tiếp viên trưởng.",en:"Politely decline because passengers with infants may not sit in exit rows, explain the safety reason, offer another roomy non-exit seat and inform the purser."},shortcut:{vi:"Cho khách ngồi 14C để tránh khiếu nại và giữ đúng giờ.",en:"Let the passenger sit in 14C to avoid a complaint and stay on time."},wait:{vi:"Để khách tự ngồi đâu cũng được, sau khi cất cánh mới xử lý.",en:"Let the passenger sit anywhere and deal with it after take-off."}},questions:{vi:["Vì sao khách ghế 3A phải mang mã WCHC? Mã này thay đổi việc chuẩn bị nhân lực, thiết bị và kế hoạch sơ tán ra sao?","Trình bày cách tính tổng khách trên tàu và vì sao không được đóng cửa khi số đếm chưa khớp loadsheet."],en:["Why must the passenger in 3A be coded WCHC? How does this change staffing, equipment and evacuation planning?","Explain how you calculated the total on board and why doors must not close until the headcount matches the loadsheet."]},hints:{vi:["Đọc mô tả khả năng di chuyển của khách ghế 3A và so với định nghĩa từng mã SSR trên danh sách đã duyệt.","Áp dụng SOP mục 3.2: trừ khách đã hạ tải và nhớ cộng cả em bé bế tay.","Đọc lại SOP mục 4.2: quy định ghế hàng cửa thoát hiểm không có ngoại lệ cho hạng thẻ thành viên."],en:["Read how the passenger in 3A can move and compare it with each SSR definition on the approved list.","Apply SOP 3.2: remove offloaded passengers and remember to add lap infants.","Re-read SOP 4.2: exit row rules have no exceptions for loyalty tiers."]}},learning:{summary:{vi:"Tiếp viên hàng không bảo đảm an toàn, an ninh và phục vụ hành khách trên tàu bay: kiểm tra thiết bị khẩn nguy trước chuyến, hướng dẫn an toàn, giám sát khoang khách, hỗ trợ khách cần trợ giúp đặc biệt, xử lý tình huống y tế, gây rối, cháy khói và chỉ huy sơ tán khi khẩn cấp. Bên cạnh dịch vụ tận tâm, nghề đòi hỏi kỷ luật quy trình, giao tiếp đa văn hóa và bình tĩnh ra quyết định dưới áp lực.",en:"Cabin crew ensure safety, security and service on board: checking emergency equipment before flight, giving safety briefings, monitoring the cabin, assisting passengers with special needs, handling medical events, disruptive passengers, smoke or fire and leading evacuations. Alongside caring service, the role demands procedural discipline, cross-cultural communication and calm decisions under pressure."},responsibilities:{vi:["Họp trước chuyến, kiểm tra thiết bị khẩn nguy, cửa và khoang bếp theo danh mục.","Đón khách, kiểm tra ghế hàng cửa thoát hiểm, hành lý xách tay và khách cần hỗ trợ đặc biệt.","Trình diễn hướng dẫn an toàn, kiểm tra khoang khách trước cất cánh và hạ cánh.","Phục vụ ăn uống, bán hàng trên tàu và chăm sóc khách theo tiêu chuẩn của hãng.","Sơ cứu, xử lý khách gây rối, cháy khói trong khoang và tổ chức sơ tán khi khẩn cấp."],en:["Attend the pre-flight briefing and check emergency equipment, doors and galleys against checklists.","Board passengers and check exit rows, cabin baggage and passengers needing special assistance.","Deliver the safety demonstration and secure the cabin before take-off and landing.","Serve meals, run on-board sales and care for passengers to the airline standard.","Give first aid, manage disruptive passengers, smoke or fire in the cabin and lead evacuations."]},competencies:[{name:{vi:"An toàn & thoát hiểm",en:"Safety & evacuation"},desc:{vi:"Thuộc vị trí, cách dùng thiết bị khẩn nguy và lệnh sơ tán trên từng loại tàu bay.",en:"Know the location and use of emergency equipment and the evacuation commands for each aircraft type."}},{name:{vi:"Phục vụ khách hàng",en:"Customer service"},desc:{vi:"Chăm sóc tận tình, nhận diện nhu cầu đặc biệt và giữ trải nghiệm nhất quán.",en:"Provide attentive care, recognise special needs and keep the experience consistent."}},{name:{vi:"Xử lý xung đột",en:"Conflict handling"},desc:{vi:"Từ chối yêu cầu không an toàn một cách lịch sự, đưa ra lựa chọn thay thế và hạ nhiệt tình huống.",en:"Decline unsafe requests politely, offer alternatives and de-escalate."}},{name:{vi:"Sơ cứu & y tế hàng không",en:"First aid & aviation medicine"},desc:{vi:"Đánh giá ban đầu, sơ cứu, dùng thiết bị y tế trên tàu và phối hợp hỗ trợ y tế từ mặt đất.",en:"Assess, give first aid, use on-board medical kits and coordinate ground medical support."}},{name:{vi:"Phối hợp tổ bay (CRM)",en:"Crew resource management"},desc:{vi:"Trao đổi rõ ràng với tổ lái và tiếp viên khác, báo cáo kịp thời mọi bất thường.",en:"Communicate clearly with the flight deck and other crew and report any irregularity promptly."}}],knowledge:{vi:["Phụ lục 6 Công ước Chicago (ICAO Annex 6) về khai thác tàu bay và yêu cầu đối với tổ tiếp viên.","Quy định ghế hàng cửa thoát hiểm: khách phải đủ khả năng hỗ trợ mở cửa, không bế em bé, không cần trợ giúp đặc biệt.","Mã yêu cầu dịch vụ đặc biệt của IATA như WCHR, WCHS, WCHC, UMNR, MEDA và thủ tục phục vụ tương ứng.","Hướng dẫn ICAO Doc 9481 về ứng phó sự cố hàng nguy hiểm trên tàu bay, như pin lithium quá nhiệt.","Nguyên tắc quản lý nguồn lực tổ bay (CRM) và quy trình xử lý hành khách gây rối."],en:["ICAO Annex 6 on aircraft operations and cabin crew requirements.","Exit row rules: passengers must be able to assist with the exit, not hold an infant and not need special help.","IATA special service request codes such as WCHR, WCHS, WCHC, UMNR and MEDA and the matching procedures.","ICAO Doc 9481 on responding to dangerous goods incidents on board, such as overheating lithium batteries.","Crew resource management (CRM) principles and procedures for disruptive passengers."]},tools:["Danh mục kiểm tra thiết bị khẩn nguy","Hệ thống thông báo & liên lạc nội bộ","Bộ sơ cứu & túi y tế","Bình chữa cháy & túi cách ly pin lithium","Thiết bị bán hàng trên tàu"],kpis:{vi:["Tỷ lệ chuyến đóng cửa đúng giờ mà không vi phạm quy trình an toàn.","Điểm hài lòng hành khách theo khảo sát sau chuyến.","Số sai lệch an toàn bị phát hiện qua kiểm tra đột xuất (mục tiêu bằng 0).","Tỷ lệ báo cáo sự kiện khoang khách đầy đủ, đúng hạn."],en:["Share of flights closing on time with no safety procedure breach.","Passenger satisfaction score from post-flight surveys.","Safety deviations found in spot checks (target zero).","Share of cabin event reports filed completely and on time."]},day:[{time:"05:30",vi:"Điểm danh, họp tổ bay, nhận thông tin chuyến bay và danh sách khách đặc biệt.",en:"Sign in, attend the crew briefing and receive flight details and the special passenger list."},{time:"06:15",vi:"Kiểm tra thiết bị khẩn nguy, khoang bếp và vệ sinh khoang khách.",en:"Check emergency equipment, galleys and cabin cleanliness."},{time:"06:45",vi:"Đón khách, kiểm tra hàng ghế thoát hiểm và đếm khách đối chiếu loadsheet.",en:"Board passengers, check exit rows and do a headcount against the loadsheet."},{time:"07:30",vi:"Phục vụ trên chuyến bay, theo dõi khách cần hỗ trợ và tình trạng khoang.",en:"Serve in flight and monitor passengers needing help and the cabin condition."},{time:"09:30",vi:"Hạ cánh, hỗ trợ khách xe lăn rời tàu, viết báo cáo chuyến và bàn giao.",en:"Land, help wheelchair passengers disembark, write the flight report and hand over."}],mistakes:{vi:["Quên cộng em bé bế tay khi đếm khách khiến số đếm không khớp loadsheet.","Xếp khách bế em bé hoặc khách cần hỗ trợ vào hàng ghế cửa thoát hiểm.","Chọn sai mã hỗ trợ xe lăn, khiến thiếu nhân lực và thiết bị nâng khi lên xuống tàu."],en:["Forgetting lap infants in the headcount so it does not match the loadsheet.","Seating a passenger with an infant or needing help in an exit row.","Choosing the wrong wheelchair code, leaving too few staff and no lifting equipment at boarding."]},career:[{vi:"Tiếp viên hạng phổ thông",en:"Economy cabin crew"},{vi:"Tiếp viên hạng thương gia",en:"Business class cabin crew"},{vi:"Tiếp viên trưởng",en:"Purser / Cabin manager"},{vi:"Giáo viên huấn luyện, quản lý đội tiếp viên",en:"Cabin crew instructor, crew manager"}],glossary:[{term:"SSR",vi:"Mã yêu cầu dịch vụ đặc biệt gắn với đặt chỗ, báo cho tổ bay biết nhu cầu của khách.",en:"Special service request code on the booking that tells the crew a passenger's needs."},{term:"WCHC",vi:"Khách không tự di chuyển được, cần xe lăn và hỗ trợ đến tận ghế ngồi.",en:"Passenger who is completely immobile and needs a wheelchair and help right to the seat."},{term:"Loadsheet",vi:"Bảng cân bằng tải ghi số khách, hàng hóa, nhiên liệu và trọng tâm tàu bay.",en:"Load and trim sheet listing passengers, cargo, fuel and the aircraft centre of gravity."},{term:"Exit row",vi:"Hàng ghế cạnh cửa thoát hiểm, khách ngồi đó phải có khả năng hỗ trợ mở cửa khi khẩn cấp.",en:"Seats next to an emergency exit whose occupants must be able to help open it."},{term:"CRM",vi:"Quản lý nguồn lực tổ bay: phối hợp, giao tiếp, ra quyết định chung giữa các thành viên.",en:"Crew resource management: teamwork, communication and shared decision making."}],quiz:[{q:{vi:"Khách đi lại được trong khoang nhưng không tự lên xuống cầu thang dùng mã nào?",en:"Which code fits a passenger who can walk in the cabin but cannot climb steps?"},options:{vi:["WCHR","WCHC","WCHS","MEDA"],en:["WCHR","WCHC","WCHS","MEDA"]},answer:2,explain:{vi:"WCHS: không lên xuống bậc được nhưng tự đi lại trong khoang; WCHC: không tự di chuyển.",en:"WCHS: cannot manage steps but can walk in the cabin; WCHC: completely immobile."}},{q:{vi:"Chuyến có 150 người lớn đã lên tàu, 6 trẻ em và 3 em bé bế tay. Tổng hành khách trên tàu là bao nhiêu?",en:"A flight has 150 adults boarded, 6 children and 3 lap infants. How many passengers are on board?"},options:{vi:["156","159","153","150"],en:["156","159","153","150"]},answer:1,explain:{vi:"150 + 6 + 3 = 159; em bé bế tay vẫn phải tính vào số người trên tàu.",en:"150 + 6 + 3 = 159; lap infants are still counted on board."}},{q:{vi:"Khách hạng thẻ cao bế em bé đòi ngồi hàng cửa thoát hiểm. Bạn làm gì?",en:"A top-tier passenger with an infant insists on an exit row seat. What do you do?"},options:{vi:["Lịch sự từ chối, giải thích lý do an toàn và đề xuất ghế khác","Cho ngồi vì là khách quan trọng","Cho ngồi nếu khách ký cam kết","Mặc kệ, để tiếp viên khác xử lý"],en:["Politely decline, explain the safety reason and offer another seat","Allow it because the passenger is important","Allow it if the passenger signs a waiver","Ignore it and leave it to another crew member"]},answer:0,explain:{vi:"Quy định ghế hàng thoát hiểm là yêu cầu an toàn bắt buộc, không có ngoại lệ thương mại.",en:"Exit row rules are mandatory safety requirements with no commercial exceptions."}},{q:{vi:"Sạc dự phòng của khách bốc khói trong khoang. Hành động ưu tiên là gì?",en:"A passenger's power bank starts smoking in the cabin. What is the priority action?"},options:{vi:["Chờ hạ cánh rồi xử lý","Mở cửa sổ cho thoát khói","Bỏ vào thùng rác khoang bếp","Báo tổ lái, dập lửa nếu có, làm mát bằng nước hoặc chất lỏng không cồn và cách ly thiết bị"],en:["Wait until landing","Open a window to vent the smoke","Put it in the galley waste bin","Alert the flight deck, extinguish any fire, cool it with water or a non-alcoholic liquid and isolate it"]},answer:3,explain:{vi:"Theo hướng dẫn ứng phó pin lithium, cần thông báo tổ lái, dập lửa, làm mát để ngăn cháy lan nhiệt và theo dõi liên tục.",en:"Lithium battery guidance calls for alerting the flight deck, extinguishing, cooling to stop thermal runaway and monitoring."}}],tools_en:["Emergency equipment checklist","PA & interphone system","First aid kit & medical kit","Extinguisher & lithium battery containment bag","Inflight sales equipment"]}},"KK-988":{scenario:{company:"Phương Nam Aero Technics",supervisor:{name:"Kiều Văn Thắng",role:{vi:"Trưởng ca bảo dưỡng ngoại trường (B1)",en:"Line Maintenance Shift Lead (B1)"}},ref_code:"WO-8812",title:{vi:"Đúng vật liệu gioăng. Đúng mô-men siết. Chỉ ký việc đã làm.",en:"Right seal material. Right torque. Sign only for work done."},brief:{vi:"Tàu mô phỏng KX-731 rò rỉ dầu tại khớp nối B-nut ống áp suất bơm số 2 của hệ thủy lực xanh. Bạn thay O-ring và siết lại khớp nối bằng cờ lê lực dài hiệu dụng 12 in có lắp đầu crowfoot thẳng trục dài 3 in; mô-men yêu cầu 360 in-lb (mô phỏng). Phiếu công việc nháp WO-8812 ghi vật liệu gioăng NBR và giá trị đặt trên cờ lê 360 in-lb. Dùng terminal tra dữ liệu, đối chiếu AMM/IPC đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"Training aircraft KX-731 leaks fluid at the B-nut of the pump 2 pressure line in the green hydraulic system. You replace the O-ring and re-torque the fitting with a torque wrench of 12 in effective length fitted with a 3 in inline crowfoot; required torque is 360 in-lb (training value). Draft work order WO-8812 lists seal material NBR and a wrench setting of 360 in-lb. Use the terminal, compare with the approved AMM/IPC, correct both fields and write an evidence-based report."},reference_title:{vi:"AMM/IPC chương 29 đã phê duyệt · WO-8812",en:"Approved AMM/IPC chapter 29 · WO-8812"},fields:[{id:"SEAL_MAT",label:{vi:"Vật liệu O-ring",en:"O-ring material"},initial:"NBR",expected:"EPR",choices:["NBR","EPR","FKM"],reference:"IPC 29-11 - danh mục phụ tùng",hint:{vi:"Kiểm tra loại dầu thủy lực của hệ: gioăng nitrile chỉ hợp với dầu gốc khoáng, không chịu được dầu phosphate ester.",en:"Check the system fluid: nitrile seals suit mineral oil only and cannot withstand phosphate ester fluid."}},{id:"TORQUE_SET",label:{vi:"Giá trị đặt trên cờ lê (in-lb)",en:"Wrench setting (in-lb)"},initial:"360",expected:"288",reference:"AMM 29-11 - bảng mô-men siết",ref_value:{vi:"Mô-men yêu cầu 360 in-lb; cờ lê L = 12 in; đầu crowfoot thẳng trục E = 3 in",en:"Required torque 360 in-lb; wrench L = 12 in; inline crowfoot E = 3 in"},hint:{vi:"Đầu nối thẳng trục làm dài cánh tay đòn: đặt nguyên 360 trên cờ lê sẽ siết quá lực.",en:"An inline extension lengthens the lever arm: setting 360 on the wrench will over-torque the fitting."}}],sop32:{vi:"Khi lắp đầu nối thẳng trục: giá trị đặt trên cờ lê = mô-men yêu cầu x L ÷ (L + E), với L là chiều dài hiệu dụng của cờ lê, E là chiều dài đầu nối; làm tròn đến 1 in-lb.",en:"With an inline extension: wrench setting = required torque x L ÷ (L + E), where L is the wrench effective length and E the extension length; round to 1 in-lb."},context:{label:"CMMS / WO-8812",metrics:[{label:{vi:"Mô-men yêu cầu",en:"Required torque"},value:"360 in-lb"},{label:{vi:"Cờ lê L / đầu nối E",en:"Wrench L / extension E"},value:"12 in / 3 in"},{label:{vi:"Dầu thủy lực hệ xanh",en:"Green system fluid"},value:"Phosphate ester type IV"}]},terminal:{system:"mx-term",settable:["SEAL_MAT","TORQUE_SET"],commands:[{cmd:"status",out:{vi:"WO-8812 đang mở: rò rỉ tại B-nut ống áp suất bơm số 2, hệ thủy lực xanh. Đã xả áp, gioăng cũ đã tháo. Tàu dự kiến khởi hành sau 40 phút.",en:"WO-8812 open: leak at the pump 2 pressure line B-nut, green hydraulic system. Pressure released, old seal removed. Departure planned in 40 minutes."}},{cmd:"cat fluid.spec",out:{vi:"Hệ thủy lực xanh: dầu gốc phosphate ester loại IV. Cấm dùng gioăng và dầu dành cho hệ gốc khoáng.",en:"Green hydraulic system: phosphate ester fluid type IV. Seals and fluids for mineral oil systems are prohibited."}},{cmd:"cat ipc-29-11.txt",out:{vi:"Mục 40: O-ring khớp nối áp suất, vật liệu EPR, tương thích phosphate ester. Loại NBR chỉ dùng cho hệ gốc khoáng, không lắp lẫn.",en:"Item 40: pressure fitting O-ring, EPR material, phosphate ester compatible. NBR type is for mineral oil systems only, not interchangeable."}},{cmd:"cat amm-29-11.txt",out:{vi:"Mô-men siết B-nut: 360 in-lb (mô phỏng). Khi dùng đầu nối dài, hiệu chỉnh giá trị đặt theo chiều dài cánh tay đòn.",en:"B-nut torque: 360 in-lb (training value). When an extension is used, correct the setting for the lever arm length."}},{cmd:"tool info tw-114",out:{vi:"Cờ lê lực TW-114: chiều dài hiệu dụng L = 12 in, còn hạn hiệu chuẩn. Đầu crowfoot CF-08 lắp thẳng trục, E = 3 in.",en:"Torque wrench TW-114: effective length L = 12 in, calibration valid. Crowfoot CF-08 fitted inline, E = 3 in."}},{cmd:"leak check",out:{vi:"Chưa thực hiện. Yêu cầu: chạy bơm số 2, giữ áp suất hệ thống 5 phút, xác nhận không rò rỉ trước khi ký CRS.",en:"Not done. Required: run pump 2, hold system pressure for 5 minutes and confirm no leak before signing the CRS."}}]},crisis:{vi:"Trưởng ca nhắn: “Tàu còn 40 phút là khởi hành. Kho chỉ còn gioăng NBR, cứ lắp tạm, đặt 360 cho nhanh rồi ký CRS luôn, chạy thử rò rỉ để chuyến về làm cũng được.”",en:"The shift lead texts: “Departure in 40 minutes. Stores only have NBR seals, fit one for now, set 360 to save time and sign the CRS, the leak check can wait for the return flight.”"},options:{safe:{vi:"Từ chối lắp gioăng NBR và ký CRS khi chưa kiểm tra rò rỉ; báo MCC và bộ phận chất lượng, đề nghị hoãn chuyến hoặc đổi tàu, ghi rõ tình trạng vào sổ kỹ thuật.",en:"Refuse to fit the NBR seal or sign the CRS before a leak check; inform MCC and Quality, request a delay or aircraft swap and record the status in the tech log."},shortcut:{vi:"Lắp gioăng NBR, đặt cờ lê 360 in-lb và ký CRS cho kịp giờ.",en:"Fit the NBR seal, set the wrench to 360 in-lb and sign the CRS to make the slot."},wait:{vi:"Bỏ dở công việc, để ca sau tự quyết.",en:"Leave the job unfinished and let the next shift decide."}},questions:{vi:["Vì sao phải dùng gioăng EPR thay cho NBR? Dữ liệu nào từ terminal và IPC chứng minh điều đó?","Trình bày cách hiệu chỉnh mô-men khi dùng đầu crowfoot và hậu quả nếu ký CRS trước khi kiểm tra rò rỉ."],en:["Why must an EPR seal be used instead of NBR? Which terminal and IPC data prove it?","Explain how you corrected the torque for the crowfoot and the consequences of signing the CRS before a leak check."]},hints:{vi:["Chạy lệnh tra loại dầu của hệ và đối chiếu với mục phụ tùng trong IPC trước khi chọn gioăng.","Lấy L và E từ thông tin dụng cụ rồi áp dụng công thức hiệu chỉnh ở SOP mục 3.2.","Đọc lại SOP mục 4.2: chỉ ký CRS cho công việc đã hoàn thành và kiểm tra theo tài liệu được phê duyệt."],en:["Run the command that shows the system fluid and compare it with the IPC item before choosing a seal.","Take L and E from the tool information, then apply the correction formula in SOP 3.2.","Re-read SOP 4.2: sign the CRS only for work completed and checked to approved data."]}},learning:{summary:{vi:"Kỹ sư bảo dưỡng máy bay hạng B1 (cơ khí, động cơ, điện cơ bản) và B2 (điện, điện tử hàng không) thực hiện, giám sát và ký chứng nhận cho phép khai thác (CRS) sau bảo dưỡng theo tài liệu được phê duyệt như AMM, IPC, TSM, MEL. Nghề đòi hỏi kỹ năng chẩn đoán, tuân thủ tuyệt đối tài liệu kỹ thuật, quản lý yếu tố con người và trung thực khi ký hồ sơ, vì mỗi chữ ký gắn trực tiếp với an toàn bay.",en:"B1 (mechanical, powerplant, basic electrical) and B2 (avionics and electrical) aircraft maintenance engineers perform, supervise and certify maintenance with a certificate of release to service (CRS) using approved data such as the AMM, IPC, TSM and MEL. The role requires diagnostic skill, strict adherence to technical data, human factors awareness and honesty in records, because every signature is tied directly to flight safety."},responsibilities:{vi:["Thực hiện kiểm tra trước chuyến, kiểm tra hằng ngày, hằng tuần và các gói bảo dưỡng định kỳ.","Chẩn đoán, khắc phục hỏng hóc theo AMM, sơ đồ hệ thống và hướng dẫn tìm lỗi (TSM).","Tra cứu IPC để chọn đúng phụ tùng, vật tư, kiểm tra hiệu lực áp dụng và khả năng lắp lẫn.","Áp dụng MEL để trì hoãn hỏng hóc đúng hạng mục, đúng thời hạn và thủ tục.","Ghi sổ kỹ thuật, ký CRS và lưu hồ sơ bảo dưỡng đầy đủ, chính xác."],en:["Perform pre-flight, daily and weekly checks and scheduled maintenance packages.","Troubleshoot and rectify defects using the AMM, system schematics and the TSM.","Use the IPC to select correct parts and materials and check effectivity and interchangeability.","Apply the MEL to defer defects in the right category, time limit and procedure.","Complete the tech log, sign the CRS and keep complete, accurate maintenance records."]},competencies:[{name:{vi:"Chẩn đoán hệ thống tàu bay",en:"Aircraft system troubleshooting"},desc:{vi:"Phân tích triệu chứng, đọc sơ đồ và cô lập hỏng hóc theo trình tự logic của TSM.",en:"Analyse symptoms, read schematics and isolate faults following the TSM logic."}},{name:{vi:"Tra cứu tài liệu kỹ thuật",en:"Technical data use"},desc:{vi:"Dùng đúng phiên bản AMM, IPC, MEL và kiểm tra hiệu lực áp dụng cho từng số tàu.",en:"Use the current AMM, IPC and MEL revision and check effectivity for each aircraft."}},{name:{vi:"Thực hành tiêu chuẩn",en:"Standard practices"},desc:{vi:"Siết đúng mô-men, khóa an toàn, chọn vật liệu tương thích và dùng dụng cụ còn hạn hiệu chuẩn.",en:"Apply correct torque and locking, choose compatible materials and use calibrated tools."}},{name:{vi:"Yếu tố con người",en:"Human factors"},desc:{vi:"Nhận diện áp lực thời gian, mệt mỏi, tự mãn và dừng lại khi điều kiện không an toàn.",en:"Recognise time pressure, fatigue and complacency and stop when conditions are unsafe."}},{name:{vi:"Trách nhiệm ký CRS",en:"CRS accountability"},desc:{vi:"Chỉ ký khi công việc đã hoàn thành, đã kiểm tra và hồ sơ phản ánh đúng thực tế.",en:"Sign only when work is complete, inspected and the records reflect reality."}}],knowledge:{vi:["EASA Part-66 về giấy phép kỹ sư bảo dưỡng các hạng A, B1, B2, C và phạm vi quyền ký.","EASA Part-145 về tổ chức bảo dưỡng được phê chuẩn và thủ tục ký CRS.","Hệ thống đánh số chương ATA (iSpec 2200) để tra cứu AMM, IPC, TSM, WDM.","Thực hành tiêu chuẩn: hiệu chỉnh mô-men khi dùng đầu nối, khóa an toàn, tương thích gioăng với dầu thủy lực.","Danh mục thiết bị tối thiểu (MEL) và các hạng mục trì hoãn A, B, C, D.","Yếu tố con người trong bảo dưỡng (Dirty Dozen) và hệ thống báo cáo an toàn tự nguyện."],en:["EASA Part-66 on A, B1, B2 and C maintenance licences and certification privileges.","EASA Part-145 on approved maintenance organisations and CRS procedures.","ATA chapter numbering (iSpec 2200) for navigating the AMM, IPC, TSM and WDM.","Standard practices: torque correction with extensions, safety locking and seal compatibility with hydraulic fluid.","The minimum equipment list (MEL) and deferral categories A, B, C and D.","Human factors in maintenance (the Dirty Dozen) and voluntary safety reporting."]},tools:["Cờ lê lực đã hiệu chuẩn & đầu crowfoot","Phần mềm quản lý bảo dưỡng (CMMS)","Tài liệu điện tử AMM/IPC/TSM","Đồng hồ vạn năng & thiết bị thử","Đèn soi & thiết bị NDT cơ bản"],kpis:{vi:["Tỷ lệ hỏng hóc lặp lại trong 10 chuyến sau khi khắc phục.","Tỷ lệ chậm chuyến do kỹ thuật trên 100 lần cất cánh.","Số phát hiện của kiểm tra chất lượng về hồ sơ và ký CRS (mục tiêu bằng 0).","Tỷ lệ công việc hoàn thành trong thời gian quay đầu tàu theo kế hoạch."],en:["Repeat defect rate within 10 flights after rectification.","Technical delays per 100 departures.","Quality audit findings on records and CRS signing (target zero).","Share of tasks completed within the planned turnaround time."]},day:[{time:"05:00",vi:"Nhận bàn giao ca, xem sổ kỹ thuật, hỏng hóc trì hoãn và kế hoạch tàu.",en:"Take the handover and review the tech log, deferred defects and the aircraft plan."},{time:"05:30",vi:"Kiểm tra trước chuyến: đi vòng quanh tàu, kiểm tra lốp, phanh, dầu và chất lỏng.",en:"Do pre-flight checks: walk-around, tyres, brakes, oil and fluid levels."},{time:"08:00",vi:"Khắc phục báo hỏng của tổ lái theo TSM, tra IPC để lấy đúng phụ tùng.",en:"Rectify a pilot report using the TSM and the IPC to get the right part."},{time:"11:00",vi:"Thực hiện gói kiểm tra hằng tuần, ký xác nhận từng bước công việc.",en:"Carry out the weekly check package and sign off each task step."},{time:"13:30",vi:"Hoàn thiện hồ sơ, ký CRS, bàn giao ca và báo cáo vấn đề an toàn.",en:"Complete records, sign the CRS, hand over and report safety concerns."}],mistakes:{vi:["Dùng gioăng hoặc vật tư không tương thích dầu thủy lực vì chỉ chọn theo hình dáng, kích thước.","Không hiệu chỉnh mô-men khi lắp đầu nối dài, gây siết quá lực, nứt hoặc biến dạng khớp nối.","Ký CRS hoặc ký hộ cho công việc chưa tự kiểm tra, chưa chạy thử rò rỉ."],en:["Using seals or materials incompatible with the hydraulic fluid because they look the same size.","Not correcting torque with an extension, over-tightening and cracking or deforming the fitting.","Signing the CRS or signing for others on work not inspected or leak tested."]},career:[{vi:"Kỹ thuật viên bảo dưỡng hạng A",en:"Category A maintenance technician"},{vi:"Kỹ sư bảo dưỡng B1/B2",en:"B1/B2 maintenance engineer"},{vi:"Kỹ sư ký CRS có năng định loại tàu",en:"Type-rated certifying engineer"},{vi:"Trưởng ca hoặc quản lý chất lượng bảo dưỡng",en:"Shift lead or maintenance quality manager"}],glossary:[{term:"CRS",vi:"Chứng nhận cho phép khai thác sau bảo dưỡng, ký bởi người có thẩm quyền.",en:"Certificate of release to service signed by authorised staff after maintenance."},{term:"AMM",vi:"Tài liệu hướng dẫn bảo dưỡng tàu bay của nhà sản xuất, gồm quy trình và giá trị kỹ thuật.",en:"Manufacturer's aircraft maintenance manual with procedures and technical values."},{term:"IPC",vi:"Danh mục phụ tùng minh họa, xác định số phụ tùng, hiệu lực và khả năng lắp lẫn.",en:"Illustrated parts catalogue that defines part numbers, effectivity and interchangeability."},{term:"MEL",vi:"Danh mục thiết bị tối thiểu cho phép khai thác khi một số thiết bị hỏng, kèm điều kiện, thời hạn.",en:"Minimum equipment list allowing dispatch with certain items inoperative under conditions and limits."},{term:"Crowfoot",vi:"Đầu nối dạng chân quạ lắp vào cờ lê lực để siết khớp nối ở vị trí khó tiếp cận.",en:"Open-end adapter fitted to a torque wrench to reach fittings in tight spaces."}],quiz:[{q:{vi:"Mô-men yêu cầu 300 in-lb, cờ lê L = 10 in, đầu nối thẳng trục E = 2 in. Giá trị đặt trên cờ lê là bao nhiêu?",en:"Required torque is 300 in-lb, wrench L = 10 in, inline extension E = 2 in. What is the wrench setting?"},options:{vi:["300 in-lb","360 in-lb","250 in-lb","240 in-lb"],en:["300 in-lb","360 in-lb","250 in-lb","240 in-lb"]},answer:2,explain:{vi:"Giá trị đặt = 300 x 10 ÷ (10 + 2) = 250 in-lb.",en:"300 x 10 ÷ (10 + 2) = 250 in-lb."}},{q:{vi:"Hệ thủy lực dùng dầu phosphate ester cần gioăng vật liệu nào?",en:"Which seal material suits a phosphate ester hydraulic system?"},options:{vi:["EPR","NBR","Cao su tự nhiên","Silicone thông dụng"],en:["EPR","NBR","Natural rubber","General silicone"]},answer:0,explain:{vi:"Gioăng EPR tương thích dầu phosphate ester; NBR dùng cho dầu gốc khoáng và sẽ trương nở, hỏng.",en:"EPR seals are compatible with phosphate ester; NBR is for mineral oil and will swell and fail."}},{q:{vi:"Trưởng ca yêu cầu ký CRS trước, để kiểm tra rò rỉ sau chuyến bay. Bạn làm gì?",en:"The shift lead asks you to sign the CRS now and leak check after the flight. What do you do?"},options:{vi:["Ký vì trưởng ca chịu trách nhiệm","Ký nhưng ghi chú vào sổ","Nhờ người khác ký thay","Từ chối, báo MCC và chất lượng, chỉ ký khi đã kiểm tra đạt"],en:["Sign because the lead is responsible","Sign but add a note in the log","Ask someone else to sign","Refuse, inform MCC and Quality and sign only after a passed check"]},answer:3,explain:{vi:"CRS xác nhận tàu đủ điều kiện bay; ký khi chưa kiểm tra là vi phạm nghiêm trọng an toàn và pháp luật.",en:"The CRS certifies airworthiness; signing before inspection is a serious safety and legal breach."}},{q:{vi:"Tài liệu nào xác định đúng số phụ tùng và khả năng lắp lẫn cho từng số tàu?",en:"Which document defines correct part numbers and interchangeability per aircraft?"},options:{vi:["AMM","IPC","MEL","Sổ tay khai thác bay"],en:["AMM","IPC","MEL","Flight operations manual"]},answer:1,explain:{vi:"IPC liệt kê số phụ tùng, hiệu lực áp dụng và quan hệ lắp lẫn; AMM mô tả quy trình bảo dưỡng.",en:"The IPC lists part numbers, effectivity and interchangeability; the AMM describes procedures."}}],tools_en:["Calibrated torque wrench & crowfoot adapters","Maintenance management software (CMMS)","Electronic AMM/IPC/TSM manuals","Multimeter & test equipment","Inspection light & basic NDT equipment"]}},"KK-989":{scenario:{company:"Mây Bạc Airlines",supervisor:{name:"Trần Hữu Phước",role:{vi:"Trưởng ca Trung tâm Điều hành Khai thác",en:"OCC Duty Manager"}},ref_code:"OFP-7215",title:{vi:"Sân bay dự bị dùng được. Nhiên liệu đủ luật. Không đánh đổi an toàn.",en:"A usable alternate. Legal fuel. No trade-off on safety."},brief:{vi:"Chuyến bay 215 đi XKHA. TAF của sân bay dự bị gần nhất XKMB có TEMPO trần mây 200 ft, tầm nhìn 800 m trong khung giờ đến dự kiến; XKLA dự báo tốt. Số liệu kế hoạch: taxi 200 kg, nhiên liệu chuyến 5400 kg, dự phòng cuối 30 phút 1100 kg; nhiên liệu đi dự bị XKMB 1150 kg, XKLA 1650 kg. Bản nháp OFP-7215 chọn XKMB và nhiên liệu tại cửa 8120 kg. Đối chiếu OFP đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"Flight 215 is bound for XKHA. The TAF for the nearest alternate XKMB has a TEMPO of 200 ft ceiling and 800 m visibility in the ETA window; XKLA is forecast good. Planning data: taxi 200 kg, trip fuel 5400 kg, 30-minute final reserve 1100 kg; alternate fuel to XKMB 1150 kg, to XKLA 1650 kg. Draft OFP-7215 selects XKMB with block fuel of 8120 kg. Compare it with the approved OFP, correct both fields and write an evidence-based report."},reference_title:{vi:"Kế hoạch bay khai thác (OFP) đã duyệt · OFP-7215",en:"Approved operational flight plan · OFP-7215"},fields:[{id:"DEST_ALT",label:{vi:"Sân bay dự bị đích đến",en:"Destination alternate"},initial:"XKMB",expected:"XKLA",choices:["XKMB","XKLA","XKHA"],reference:"OFP đã duyệt - mục sân bay dự bị",hint:{vi:"Theo chính sách của hãng (mô phỏng), sân bay dự bị có TEMPO dưới tiêu chuẩn lập kế hoạch trong khung giờ đến thì không được chọn.",en:"Under the airline policy (training), an alternate with a TEMPO below planning minima in the ETA window may not be selected."}},{id:"BLOCK_FUEL",label:{vi:"Nhiên liệu tối thiểu tại cửa (kg)",en:"Minimum block fuel (kg)"},initial:"8120",expected:"8620",reference:"Bảng tính nhiên liệu OFP",ref_value:{vi:"Taxi 200; chuyến 5400; dự phòng chặng 5% nhiên liệu chuyến; dự bị XKLA 1650; dự phòng cuối 1100 (kg)",en:"Taxi 200; trip 5400; contingency 5% of trip; alternate XKLA 1650; final reserve 1100 (kg)"},hint:{vi:"Nhiên liệu dự bị phải tính tới sân bay dự bị đã chọn đúng; dự phòng chặng tính trên nhiên liệu chuyến.",en:"Alternate fuel must be to the correctly selected alternate; contingency is a share of trip fuel."}}],sop32:{vi:"Nhiên liệu tối thiểu tại cửa = taxi + nhiên liệu chuyến + dự phòng chặng (5% nhiên liệu chuyến) + nhiên liệu đi dự bị đích + dự phòng cuối 30 phút + nhiên liệu thêm (bài này bằng 0).",en:"Minimum block fuel = taxi + trip fuel + contingency (5% of trip) + destination alternate fuel + 30-minute final reserve + extra fuel (zero here)."},context:{label:"OFP / OFP-7215",metrics:[{label:{vi:"Nhiên liệu chuyến",en:"Trip fuel"},value:"5,400 kg"},{label:{vi:"Dự phòng cuối 30 phút",en:"Final reserve 30 min"},value:"1,100 kg"},{label:{vi:"Đi dự bị XKMB / XKLA",en:"Alternate XKMB / XKLA"},value:"1,150 / 1,650 kg"}]},crisis:{vi:"Phòng thương mại gọi: “Chọn XKMB đi cho nhẹ nhiên liệu, TEMPO thôi chắc không sao. Thêm 500 kg nhiên liệu là phải hạ 500 kg hàng của khách lớn, trưởng phòng đã hứa với họ rồi.”",en:"Commercial calls: “Plan XKMB to save fuel, it's only a TEMPO, it'll be fine. Another 500 kg of fuel means offloading 500 kg of a key customer's cargo, and the manager already promised them.”"},options:{safe:{vi:"Giữ XKLA và nhiên liệu tối thiểu 8620 kg, báo trưởng ca OCC và cơ trưởng, đề xuất hạ tải hàng theo thứ tự ưu tiên hoặc dừng kỹ thuật, ghi nhận áp lực vào báo cáo.",en:"Keep XKLA and the 8620 kg minimum, inform the OCC duty manager and the captain, propose offloading cargo by priority or a technical stop and record the pressure."},shortcut:{vi:"Chọn XKMB và giữ 8120 kg để chở đủ hàng như đã hứa.",en:"Plan XKMB with 8120 kg so all the promised cargo flies."},wait:{vi:"Để cơ trưởng tự quyết khi ra tàu, không cập nhật OFP.",en:"Leave it to the captain at the aircraft and do not update the OFP."}},questions:{vi:["Vì sao loại XKMB và chọn XKLA làm sân bay dự bị? Dữ liệu TAF nào chứng minh điều đó?","Trình bày cách tính nhiên liệu tối thiểu tại cửa và cách bạn xử lý yêu cầu ưu tiên hàng hóa của phòng thương mại."],en:["Why reject XKMB and select XKLA as the alternate? Which TAF data proves it?","Explain how you calculated minimum block fuel and how you handle Commercial's request to prioritise cargo."]},hints:{vi:["Đọc TAF của từng sân bay dự bị trong khung giờ đến dự kiến và so với tiêu chuẩn lập kế hoạch.","Cộng đủ các thành phần theo SOP mục 3.2, dự phòng chặng lấy 5% của nhiên liệu chuyến.","Đọc lại SOP mục 4.2: tải thương mại không bao giờ được ưu tiên hơn nhiên liệu tối thiểu theo quy định."],en:["Read each alternate's TAF for the ETA window and compare it with planning minima.","Add every component per SOP 3.2, with contingency at 5% of trip fuel.","Re-read SOP 4.2: commercial load never takes priority over regulatory minimum fuel."]}},learning:{summary:{vi:"Điều phái viên khai thác bay lập kế hoạch bay khai thác (OFP), tính nhiên liệu, chọn đường bay và sân bay dự bị, phân tích thời tiết, NOTAM, giới hạn trọng tải và theo dõi chuyến bay từ trung tâm điều hành khai thác (OCC). Cùng cơ trưởng chia sẻ trách nhiệm về quyết định khai thác, nghề đòi hỏi am hiểu quy định nhiên liệu, khí tượng hàng không, tính năng tàu bay và bản lĩnh giữ vững an toàn trước áp lực thương mại.",en:"A flight dispatcher prepares the operational flight plan (OFP), calculates fuel, selects routes and alternates, analyses weather, NOTAMs and weight limits and follows flights from the operations control centre (OCC). Sharing responsibility for operational decisions with the captain, the role requires knowledge of fuel rules, aviation weather and aircraft performance, and the resolve to keep safety first under commercial pressure."},responsibilities:{vi:["Lập kế hoạch bay, chọn đường bay, mực bay và sân bay dự bị phù hợp thời tiết, NOTAM.","Tính nhiên liệu theo chính sách nhiên liệu của hãng và quy định nhà chức trách.","Phân tích METAR, TAF, SIGMET, gió trên cao và thời tiết nguy hiểm trên đường bay.","Kiểm tra giới hạn trọng tải, hạng mục MEL ảnh hưởng khai thác và thông báo cho tổ lái.","Theo dõi chuyến bay, hỗ trợ tổ lái khi chuyển hướng, chậm chuyến hoặc tình huống bất thường."],en:["Plan flights, choosing routes, levels and alternates suited to weather and NOTAMs.","Calculate fuel under the airline fuel policy and authority rules.","Analyse METAR, TAF, SIGMET, upper winds and hazardous en-route weather.","Check weight limits and MEL items affecting operations and brief the crew.","Follow flights and support the crew during diversions, delays or abnormal events."]},competencies:[{name:{vi:"Lập kế hoạch nhiên liệu",en:"Fuel planning"},desc:{vi:"Tính đủ các thành phần nhiên liệu và cập nhật ngay khi đổi đường bay, sân bay dự bị.",en:"Compute every fuel component and update it as soon as routes or alternates change."}},{name:{vi:"Khí tượng hàng không",en:"Aviation meteorology"},desc:{vi:"Giải mã METAR, TAF, nhận diện nhóm TEMPO, BECMG, PROB và tác động tới tiêu chuẩn khai thác.",en:"Decode METAR and TAF, read TEMPO, BECMG and PROB groups and their effect on minima."}},{name:{vi:"Tính năng & trọng tải",en:"Performance & weight"},desc:{vi:"Kiểm tra giới hạn cất cánh, hạ cánh, trọng lượng tối đa và phân bổ tải hợp lệ.",en:"Check take-off and landing limits, maximum weights and valid load distribution."}},{name:{vi:"Theo dõi chuyến bay",en:"Flight following"},desc:{vi:"Giám sát tiến trình chuyến bay, nhiên liệu còn lại và cảnh báo sớm cho tổ lái.",en:"Monitor flight progress and remaining fuel and warn the crew early."}},{name:{vi:"Ra quyết định an toàn",en:"Safety decision making"},desc:{vi:"Giữ quyết định đúng quy định trước áp lực thương mại và ghi nhận minh bạch lý do.",en:"Hold compliant decisions under commercial pressure and record the reasons transparently."}}],knowledge:{vi:["Phụ lục 6 ICAO về yêu cầu nhiên liệu, sân bay dự bị và kiểm soát khai thác.","ICAO Doc 9976 hướng dẫn lập kế hoạch bay và quản lý nhiên liệu.","Mã thời tiết METAR, TAF và các nhóm thay đổi BECMG, TEMPO, PROB theo Phụ lục 3 ICAO.","Quy tắc khai thác tầm xa EDTO/ETOPS và yêu cầu sân bay dự bị trên đường bay.","Danh mục thiết bị tối thiểu (MEL) và tác động tới kế hoạch bay, nhiên liệu."],en:["ICAO Annex 6 on fuel requirements, alternates and operational control.","ICAO Doc 9976 on flight planning and fuel management.","METAR and TAF codes and the BECMG, TEMPO and PROB change groups under ICAO Annex 3.","EDTO/ETOPS extended range rules and en-route alternate requirements.","The minimum equipment list (MEL) and its effect on flight planning and fuel."]},tools:["Hệ thống lập kế hoạch bay","Phần mềm theo dõi chuyến bay","Cổng khí tượng hàng không","Hệ thống tra cứu NOTAM","Liên lạc dữ liệu ACARS"],kpis:{vi:["Tỷ lệ OFP đúng ngay lần đầu, không phải phát hành lại.","Chênh lệch giữa nhiên liệu kế hoạch và thực tế mỗi chuyến.","Số chuyến chuyển hướng do lập kế hoạch thiếu sót (mục tiêu bằng 0).","Thời gian phản hồi yêu cầu hỗ trợ của tổ lái."],en:["Right-first-time OFP rate with no reissue.","Difference between planned and actual fuel per flight.","Diversions caused by planning errors (target zero).","Response time to crew support requests."]},day:[{time:"06:00",vi:"Nhận bàn giao ca OCC, xem chuyến đang khai thác, hỏng hóc trì hoãn và NOTAM mới.",en:"Take the OCC handover and review active flights, deferred defects and new NOTAMs."},{time:"07:00",vi:"Phân tích thời tiết, chọn đường bay và sân bay dự bị cho các chuyến trong ca.",en:"Analyse weather and choose routes and alternates for the shift's flights."},{time:"09:00",vi:"Phát hành OFP và trao đổi với tổ lái về nhiên liệu, thời tiết.",en:"Release OFPs and brief crews on fuel and weather."},{time:"12:00",vi:"Theo dõi chuyến bay, xử lý yêu cầu chuyển hướng do thời tiết xấu.",en:"Follow flights and handle a weather diversion request."},{time:"14:00",vi:"Ghi nhật ký ca, báo cáo sự kiện và bàn giao ca sau.",en:"Complete the shift log, report events and hand over."}],mistakes:{vi:["Chọn sân bay dự bị gần nhất mà bỏ qua nhóm TEMPO dưới tiêu chuẩn trong khung giờ đến.","Tính dự phòng chặng trên tổng nhiên liệu hoặc quên cập nhật nhiên liệu khi đổi sân bay dự bị.","Cắt nhiên liệu dưới mức tối thiểu để ưu tiên hàng hóa theo yêu cầu thương mại."],en:["Choosing the nearest alternate while ignoring a TEMPO below minima in the ETA window.","Basing contingency on total fuel or not updating fuel after changing the alternate.","Cutting fuel below the minimum to favour cargo at Commercial's request."]},career:[{vi:"Trợ lý điều phái bay",en:"Assistant flight dispatcher"},{vi:"Điều phái viên khai thác bay có giấy phép",en:"Licensed flight dispatcher"},{vi:"Điều phái viên chính, trưởng ca OCC",en:"Senior dispatcher, OCC duty manager"},{vi:"Giám đốc trung tâm điều hành khai thác",en:"Head of operations control centre"}],glossary:[{term:"OFP",vi:"Kế hoạch bay khai thác gồm đường bay, mực bay, thời gian, nhiên liệu và sân bay dự bị.",en:"Operational flight plan with route, levels, times, fuel and alternates."},{term:"TAF",vi:"Bản tin dự báo thời tiết sân bay trong một khoảng thời gian xác định.",en:"Terminal aerodrome forecast for a defined period."},{term:"TEMPO",vi:"Nhóm biến đổi tạm thời trong TAF: mỗi lần dưới 1 giờ và tổng thời gian dưới một nửa thời kỳ dự báo.",en:"Temporary change group in a TAF: each spell under 1 hour, totalling less than half the period."},{term:"Contingency fuel",vi:"Nhiên liệu dự phòng chặng bù cho các yếu tố không lường trước, thường theo tỷ lệ nhiên liệu chuyến.",en:"Fuel for unforeseen factors, usually a percentage of trip fuel."},{term:"Final reserve fuel",vi:"Nhiên liệu dự phòng cuối cùng, với tàu phản lực tương ứng 30 phút bay chờ ở 1500 ft.",en:"Last reserve fuel, for jets equal to 30 minutes holding at 1500 ft."}],quiz:[{q:{vi:"Nhiên liệu chuyến 6000 kg, dự phòng chặng 5%. Dự phòng chặng là bao nhiêu?",en:"Trip fuel is 6000 kg and contingency is 5%. What is the contingency fuel?"},options:{vi:["600 kg","150 kg","500 kg","300 kg"],en:["600 kg","150 kg","500 kg","300 kg"]},answer:3,explain:{vi:"Dự phòng chặng = 5% x 6000 = 300 kg.",en:"Contingency = 5% x 6000 = 300 kg."}},{q:{vi:"Nhóm TEMPO trong TAF có nghĩa là gì?",en:"What does a TEMPO group in a TAF mean?"},options:{vi:["Thay đổi lâu dài và ổn định","Biến đổi tạm thời, mỗi lần dưới 1 giờ, tổng dưới nửa thời kỳ","Xác suất 30% xảy ra","Thời tiết đã quan trắc thực tế"],en:["A lasting, steady change","Temporary changes, each under 1 hour, totalling under half the period","A 30% probability","Actually observed weather"]},answer:1,explain:{vi:"TEMPO mô tả biến đổi tạm thời; khi dưới tiêu chuẩn tại sân bay dự bị phải được đánh giá theo chính sách của hãng.",en:"TEMPO describes temporary changes; when below minima at an alternate it must be assessed under the airline policy."}},{q:{vi:"Phòng thương mại đề nghị cắt nhiên liệu dưới mức tối thiểu để chở thêm hàng. Bạn làm gì?",en:"Commercial asks to cut fuel below the minimum to carry more cargo. What do you do?"},options:{vi:["Giữ nhiên liệu tối thiểu, báo trưởng ca và cơ trưởng, đề xuất hạ tải hàng","Đồng ý vì đường bay ngắn","Cắt một nửa phần chênh lệch","Để cơ trưởng tự xử lý"],en:["Keep minimum fuel, inform the duty manager and captain and propose offloading cargo","Agree because the sector is short","Cut half the difference","Leave it to the captain"]},answer:0,explain:{vi:"Nhiên liệu tối thiểu là yêu cầu an toàn bắt buộc; tải thương mại phải điều chỉnh theo nhiên liệu chứ không ngược lại.",en:"Minimum fuel is a mandatory safety requirement; payload must adjust to fuel, not the reverse."}},{q:{vi:"Dự phòng cuối cho tàu bay phản lực theo ICAO tương ứng với gì?",en:"Under ICAO, what does final reserve fuel for a jet correspond to?"},options:{vi:["10 phút bay bằng","60 phút bay đến sân bay dự bị","30 phút bay chờ ở 1500 ft trên sân bay ở điều kiện chuẩn","5% nhiên liệu chuyến"],en:["10 minutes of cruise","60 minutes to the alternate","30 minutes holding at 1500 ft above the aerodrome in standard conditions","5% of trip fuel"]},answer:2,explain:{vi:"Với tàu phản lực, dự phòng cuối là lượng nhiên liệu bay chờ 30 phút ở 1500 ft (450 m) trên sân bay.",en:"For jets, final reserve is the fuel to hold for 30 minutes at 1500 ft (450 m) above the aerodrome."}}],tools_en:["Flight planning system","Flight tracking software","Aviation weather portal","NOTAM lookup system","ACARS data link"]}},"KK-990":{scenario:{company:"Thanh Lam Bulk Carriers",supervisor:{name:"Ngô Quốc Bảo",role:{vi:"Thuyền trưởng",en:"Master"}},ref_code:"PP-0931",title:{vi:"Đúng quy tắc tránh va. Đủ nước dưới ki. An toàn rồi mới đúng giờ.",en:"Right COLREG rule. Enough water under the keel. Safety before schedule."},brief:{vi:"Tàu hàng rời mô phỏng chuẩn bị vào luồng hẹp. Mớn nước tĩnh 11,6 m, Cb 0,80, tốc độ kế hoạch 8 hải lý/giờ; điểm nông nhất có độ sâu hải đồ 12,4 m, thủy triều dự báo 1,85 m. Trên radar, tàu B tiếp cận từ phương vị tương đối 125° mạn phải, nhanh hơn và đang rút ngắn khoảng cách. Bản nháp kế hoạch chuyến đi PP-0931 ghi tình huống RULE-15 và UKC 265 cm. Đối chiếu bản đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"A training bulk carrier is about to enter a confined channel. Static draft 11.6 m, Cb 0.80, planned speed 8 knots; the shallowest point has a charted depth of 12.4 m and a predicted tide of 1.85 m. On radar, vessel B approaches from a relative bearing of 125° to starboard, faster and closing. Draft passage plan PP-0931 records situation RULE-15 and a UKC of 265 cm. Compare it with the approved plan, correct both fields and write an evidence-based report."},reference_title:{vi:"Kế hoạch chuyến đi đã duyệt · PP-0931",en:"Approved passage plan · PP-0931"},fields:[{id:"COLREG_RULE",label:{vi:"Tình huống tránh va áp dụng",en:"Applicable collision rule"},initial:"RULE-15",expected:"RULE-13",choices:["RULE-13","RULE-14","RULE-15"],reference:"Bảng đánh giá tình huống tránh va",hint:{vi:"Tàu đến từ hướng quá 22,5° sau trục ngang mạn (phương vị tương đối lớn hơn 112,5°) là tàu vượt, không phải cắt hướng.",en:"A vessel coming from more than 22.5° abaft the beam (relative bearing above 112.5°) is overtaking, not crossing."}},{id:"UKC_CM",label:{vi:"Độ sâu dưới ki tại điểm nông (cm)",en:"Under-keel clearance at the shoal (cm)"},initial:"265",expected:"163",reference:"Bảng tính UKC đã duyệt",ref_value:{vi:"Độ sâu hải đồ 12,4 m; triều 1,85 m; mớn tĩnh 11,6 m; Cb 0,80; V = 8 hải lý/giờ; luồng hẹp",en:"Charted depth 12.4 m; tide 1.85 m; static draft 11.6 m; Cb 0.80; V = 8 knots; confined channel"},hint:{vi:"Bản nháp quên trừ squat: tàu chạy trong luồng hẹp bị chìm thêm và mức chìm tăng theo bình phương tốc độ.",en:"The draft forgot squat: a ship in a confined channel sinks further, rising with the square of speed."}}],sop32:{vi:"UKC = độ sâu hải đồ + chiều cao triều - mớn nước tĩnh - squat; squat trong luồng hẹp = Cb x V² ÷ 50 (m, V tính bằng hải lý/giờ, công thức kinh nghiệm Barrass); đổi ra cm, làm tròn đến cm.",en:"UKC = charted depth + height of tide - static draft - squat; squat in a confined channel = Cb x V² ÷ 50 (m, V in knots, Barrass rule of thumb); convert to cm and round to the nearest cm."},context:{label:"ECDIS / PP-0931",metrics:[{label:{vi:"Mớn nước tĩnh",en:"Static draft"},value:"11.6 m"},{label:{vi:"Độ sâu hải đồ + triều",en:"Charted depth + tide"},value:"12.4 m + 1.85 m"},{label:{vi:"Tốc độ kế hoạch",en:"Planned speed"},value:"8 kn"},{label:{vi:"UKC tối thiểu theo chính sách",en:"Policy minimum UKC"},value:"10% draft"}]},crisis:{vi:"Đại lý báo cầu bến chỉ giữ chỗ đến 18:00, trễ sẽ bị phạt. Thuyền trưởng nói: “Tăng lên 11 hải lý qua luồng cho kịp, khỏi tính lại UKC, triều đang lên mà.” Ở 11 hải lý squat tăng mạnh.",en:"The agent says the berth is held only until 18:00, with penalties if late. The master says: “Go to 11 knots through the channel, no need to recalculate UKC, the tide is rising.” At 11 knots squat rises sharply."},options:{safe:{vi:"Tính lại UKC ở 11 hải lý, báo thuyền trưởng bằng văn bản rằng UKC dưới mức chính sách, đề xuất giữ 8 hải lý hoặc chờ con nước sau; nếu vẫn bị ép, ghi nhật ký và báo DPA theo ISM.",en:"Recalculate UKC at 11 knots, tell the master in writing it falls below policy, propose holding 8 knots or waiting for the next tide; if still pressed, log it and inform the DPA under the ISM Code."},shortcut:{vi:"Tăng tốc lên 11 hải lý theo lệnh, không tính lại UKC để kịp cầu bến.",en:"Increase to 11 knots as ordered without recalculating UKC to make the berth."},wait:{vi:"Im lặng giữ ca trực, để hoa tiêu và thuyền trưởng tự lo.",en:"Keep quiet on watch and leave it to the pilot and the master."}},questions:{vi:["Vì sao tình huống với tàu B là RULE-13? Khi đó tàu mình và tàu B có nghĩa vụ gì?","Trình bày cách tính UKC có squat và rủi ro nếu tăng tốc lên 11 hải lý qua luồng hẹp."],en:["Why is the encounter with vessel B a RULE-13 case? What are our duties and vessel B's duties?","Explain how you calculated UKC including squat and the risk of increasing to 11 knots in the channel."]},hints:{vi:["So phương vị tương đối của tàu B với giới hạn 22,5° sau trục ngang mạn trên bảng đánh giá.","Tính squat theo SOP mục 3.2 trước, rồi trừ cùng mớn nước tĩnh khỏi độ sâu có triều.","Đọc lại SOP mục 4.2: mọi quyết định làm giảm biên an toàn phải được ghi nhận và báo cáo theo hệ thống quản lý an toàn."],en:["Compare vessel B's relative bearing with the 22.5° abaft the beam limit on the assessment sheet.","Work out squat per SOP 3.2 first, then subtract it with the static draft from the depth plus tide.","Re-read SOP 4.2: any decision that cuts the safety margin must be logged and reported through the safety management system."]}},learning:{summary:{vi:"Sĩ quan boong đảm nhiệm ca trực buồng lái, lập và theo dõi kế hoạch chuyến đi, xác định vị trí, tránh va, giám sát làm hàng, ổn định tàu và quản lý thiết bị cứu sinh, cứu hỏa. Nghề đòi hỏi nắm vững COLREG, SOLAS, STCW, thành thạo ECDIS, radar/ARPA, tính toán UKC, ổn định và kỷ luật báo cáo theo hệ thống quản lý an toàn, kể cả khi phải nói thẳng với cấp trên.",en:"A deck officer keeps the navigational watch, prepares and monitors the passage plan, fixes position, avoids collisions, supervises cargo work and stability and manages life-saving and fire-fighting equipment. The role demands mastery of COLREG, SOLAS and STCW, skill with ECDIS and radar/ARPA, UKC and stability calculations, and disciplined reporting through the safety management system, even when it means speaking up to superiors."},responsibilities:{vi:["Đứng ca buồng lái, duy trì cảnh giới, xác định vị trí và tránh va theo COLREG.","Lập kế hoạch chuyến đi từ bến đến bến: tuyến, điểm nông, UKC, thủy triều, cảnh báo hàng hải.","Giám sát làm hàng, mớn nước, ổn định và ứng suất thân tàu.","Bảo dưỡng thiết bị hàng hải, cứu sinh, cứu hỏa và tổ chức diễn tập.","Ghi nhật ký hàng hải, báo cáo sự cố và cận nguy theo hệ thống quản lý an toàn."],en:["Keep the bridge watch, maintain lookout, fix position and avoid collisions under COLREG.","Plan the voyage berth to berth: track, shoals, UKC, tides and navigational warnings.","Supervise cargo work, draft, stability and hull stresses.","Maintain navigation, life-saving and fire-fighting equipment and run drills.","Keep the logbook and report incidents and near misses through the safety management system."]},competencies:[{name:{vi:"Hành hải & tránh va",en:"Navigation & collision avoidance"},desc:{vi:"Đánh giá nguy cơ va chạm bằng phương vị, CPA, TCPA và áp dụng đúng quy tắc COLREG.",en:"Assess collision risk with bearings, CPA and TCPA and apply the correct COLREG rule."}},{name:{vi:"Lập kế hoạch chuyến đi",en:"Passage planning"},desc:{vi:"Thẩm định, lập kế hoạch, thực hiện và giám sát tuyến đi với biên an toàn rõ ràng.",en:"Appraise, plan, execute and monitor the passage with clear safety margins."}},{name:{vi:"Ổn định & làm hàng",en:"Stability & cargo"},desc:{vi:"Tính GM, mớn nước, ứng suất và theo dõi kế hoạch xếp dỡ an toàn.",en:"Compute GM, draft and stresses and monitor a safe loading plan."}},{name:{vi:"Quản lý nguồn lực buồng lái",en:"Bridge resource management"},desc:{vi:"Phối hợp với thuyền trưởng, hoa tiêu, thủy thủ và lên tiếng khi phát hiện rủi ro.",en:"Work with the master, pilot and crew and speak up when risks appear."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Tuân thủ SMS, ghi nhật ký trung thực và báo cáo theo kênh ISM khi cần.",en:"Follow the SMS, keep honest logs and report through ISM channels when needed."}}],knowledge:{vi:["Quy tắc quốc tế phòng ngừa đâm va tàu thuyền trên biển (COLREG 1972).","Công ước SOLAS, chương V về an toàn hành hải và kế hoạch chuyến đi.","Công ước STCW về tiêu chuẩn huấn luyện, cấp chứng chỉ và trực ca.","Bộ luật ISM về quản lý an toàn và vai trò người phụ trách trên bờ (DPA).","Hướng dẫn lập kế hoạch chuyến đi của IMO theo Nghị quyết A.893(21).","Tính UKC, squat, ổn định tàu và hiệu chỉnh mớn nước theo tỷ trọng nước."],en:["International Regulations for Preventing Collisions at Sea (COLREG 1972).","SOLAS chapter V on safety of navigation and passage planning.","The STCW Convention on training, certification and watchkeeping.","The ISM Code on safety management and the role of the designated person ashore (DPA).","IMO guidelines for voyage planning, Resolution A.893(21).","UKC, squat and stability calculations and draft correction for water density."]},tools:["ECDIS","Radar/ARPA","Hệ thống nhận dạng tự động (AIS)","Máy đo sâu hồi âm","Phần mềm tính ổn định & tải trọng"],kpis:{vi:["Số cận nguy và sự cố hành hải trong chuyến (mục tiêu bằng 0).","Tỷ lệ kế hoạch chuyến đi được kiểm tra, phê duyệt trước khi khởi hành.","Số khiếm khuyết về hàng hải trong kiểm tra của chính quyền cảng (PSC).","Tỷ lệ diễn tập và bảo dưỡng thiết bị hoàn thành đúng kế hoạch."],en:["Navigational near misses and incidents per voyage (target zero).","Share of passage plans checked and approved before departure.","Navigation deficiencies found in port state control (PSC) inspections.","Share of drills and equipment maintenance completed on schedule."]},day:[{time:"04:00",vi:"Nhận ca 04-08, kiểm tra vị trí, radar, AIS và lệnh đêm của thuyền trưởng.",en:"Take the 04-08 watch and check position, radar, AIS and the master's night orders."},{time:"06:30",vi:"Đọc mớn nước, cập nhật thủy triều và tính UKC cho đoạn luồng vào cảng.",en:"Read drafts, update tides and calculate UKC for the port approach channel."},{time:"08:00",vi:"Bàn giao ca, cập nhật nhật ký hàng hải và báo cáo vị trí.",en:"Hand over the watch, update the logbook and send the position report."},{time:"14:00",vi:"Bảo dưỡng thiết bị cứu sinh, cứu hỏa và chuẩn bị diễn tập.",en:"Maintain life-saving and fire-fighting gear and prepare a drill."},{time:"16:00",vi:"Nhận ca 16-20, phối hợp hoa tiêu vào luồng và giám sát tàu thuyền xung quanh.",en:"Take the 16-20 watch, work with the pilot in the channel and monitor nearby traffic."}],mistakes:{vi:["Quên trừ squat hoặc dùng sai giờ thủy triều khi tính UKC.","Đánh giá nhầm tình huống vượt thành cắt hướng do không đo phương vị tương đối chính xác.","Giữ im lặng khi kế hoạch bị ép giảm biên an toàn, không ghi nhật ký và không báo cáo."],en:["Forgetting squat or using the wrong tide time when calculating UKC.","Mistaking overtaking for crossing by not measuring the relative bearing accurately.","Staying silent when the safety margin is cut, without logging or reporting it."]},career:[{vi:"Sĩ quan boong tập sự",en:"Deck cadet"},{vi:"Sĩ quan boong (phó ba, phó hai)",en:"Third or second officer"},{vi:"Đại phó",en:"Chief officer"},{vi:"Thuyền trưởng",en:"Master"}],glossary:[{term:"UKC",vi:"Độ sâu dưới ki: khoảng nước còn lại giữa đáy tàu và đáy luồng.",en:"Under-keel clearance: the water left between the keel and the seabed."},{term:"Squat",vi:"Hiện tượng tàu chìm thêm khi chạy do áp suất nước dưới thân tàu giảm, tăng theo tốc độ.",en:"Extra sinkage of a moving ship due to lower pressure under the hull, increasing with speed."},{term:"Stand-on vessel",vi:"Tàu được nhường đường, phải giữ hướng và tốc độ nhưng vẫn phải hành động khi tàu kia không tránh.",en:"Vessel that keeps course and speed but must act if the give-way vessel does not."},{term:"ECDIS",vi:"Hệ thống hiển thị hải đồ điện tử và thông tin, dùng để lập và theo dõi tuyến đi.",en:"Electronic chart display and information system for planning and monitoring the route."},{term:"DPA",vi:"Người phụ trách trên bờ theo Bộ luật ISM, có quyền tiếp cận lãnh đạo cao nhất của công ty.",en:"Designated person ashore under the ISM Code with direct access to top management."}],quiz:[{q:{vi:"Tàu khác tiến đến từ hướng quá 22,5° sau trục ngang mạn của tàu mình là tình huống nào?",en:"A vessel approaching from more than 22.5° abaft your beam creates which situation?"},options:{vi:["Đối hướng (Rule 14)","Cắt hướng (Rule 15)","Vượt (Rule 13)","Tầm nhìn hạn chế (Rule 19)"],en:["Head-on (Rule 14)","Crossing (Rule 15)","Overtaking (Rule 13)","Restricted visibility (Rule 19)"]},answer:2,explain:{vi:"Theo Rule 13, tàu đến từ hướng quá 22,5° sau trục ngang mạn là tàu vượt và phải tránh đường.",en:"Under Rule 13, a vessel coming from more than 22.5° abaft the beam is overtaking and must keep clear."}},{q:{vi:"Cb 0,75, tốc độ 10 hải lý/giờ trong luồng hẹp. Squat theo Cb x V² ÷ 50 là bao nhiêu?",en:"Cb 0.75 at 10 knots in a confined channel. What is squat by Cb x V² ÷ 50?"},options:{vi:["0,75 m","1,5 m","3,0 m","1,0 m"],en:["0.75 m","1.5 m","3.0 m","1.0 m"]},answer:1,explain:{vi:"Độ chìm squat = 0,75 x 100 ÷ 50 = 1,5 m.",en:"Squat = 0.75 x 100 ÷ 50 = 1.5 m."}},{q:{vi:"Thuyền trưởng yêu cầu tăng tốc qua luồng nông mà không tính lại UKC. Sĩ quan ca nên làm gì?",en:"The master orders a speed increase through a shallow channel without recalculating UKC. What should the officer of the watch do?"},options:{vi:["Làm theo vì thuyền trưởng quyết định","Tự giảm tốc mà không báo ai","Bỏ ca trực để phản đối","Tính lại UKC, báo cáo bằng văn bản, đề xuất phương án an toàn và ghi nhật ký"],en:["Comply because the master decides","Reduce speed without telling anyone","Leave the watch in protest","Recalculate UKC, report in writing, propose a safe option and log it"]},answer:3,explain:{vi:"Sĩ quan phải lên tiếng bằng số liệu, đề xuất phương án an toàn và ghi nhận để hệ thống ISM xử lý.",en:"The officer must speak up with data, propose a safe option and record it for the ISM system."}},{q:{vi:"Theo Bộ luật ISM, DPA là ai?",en:"Under the ISM Code, who is the DPA?"},options:{vi:["Người phụ trách trên bờ có quyền tiếp cận lãnh đạo cao nhất","Hoa tiêu dẫn tàu","Đại lý tàu tại cảng","Thanh tra chính quyền cảng"],en:["The shore-based person with access to top management","The harbour pilot","The port agent","The port state inspector"]},answer:0,explain:{vi:"DPA là cầu nối giữa tàu và lãnh đạo cao nhất, giám sát an toàn và tiếp nhận báo cáo của thuyền viên.",en:"The DPA links ship and top management, monitors safety and receives crew reports."}}],tools_en:["ECDIS","Radar/ARPA","Automatic Identification System (AIS)","Echo sounder","Loading and stability software"]}},"KK-991":{scenario:{company:"Ngọc Hà Ocean Chartering",supervisor:{name:"Phan Thị Thu Trang",role:{vi:"Trưởng phòng Khai thác & Thuê tàu",en:"Head of Chartering & Operations"}},ref_code:"LT-5520",title:{vi:"Đúng điều khoản laytime. Đúng tiền phạt chậm. SOF trung thực.",en:"Right laytime terms. Right demurrage. A truthful SOF."},brief:{vi:"Tàu xếp 33.000 tấn than tại cảng xếp với mức xếp 6.000 tấn/ngày. Laytime bắt đầu tính từ 08:00 thứ Năm, xếp xong lúc 23:00 thứ Năm tuần sau; không có ngày lễ, không ngừng do thời tiết. Mức phạt bốc dỡ chậm 16.800 USD/ngày, tính theo tỷ lệ thời gian. Bản nháp bảng tính LT-5520 áp điều khoản SHINC và tính phạt 35700 USD. Đối chiếu hợp đồng thuê tàu đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"A vessel loads 33,000 t of coal at a loading rate of 6,000 t per day. Laytime starts at 08:00 on Thursday and loading completes at 23:00 the following Thursday; there are no holidays and no weather stoppages. Demurrage is 16,800 USD per day, pro rata. Draft laytime statement LT-5520 applies SHINC terms and claims 35700 USD. Compare it with the approved charter party, correct both fields and write an evidence-based report."},reference_title:{vi:"Hợp đồng thuê chuyến & SOF đã ký · LT-5520",en:"Approved charter party & signed SOF · LT-5520"},fields:[{id:"LAY_TERMS",label:{vi:"Điều khoản tính laytime",en:"Laytime counting terms"},initial:"SHINC",expected:"SHEX",choices:["SHINC","SHEX","SSHEX"],reference:"Hợp đồng thuê chuyến - điều khoản laytime",hint:{vi:"Hợp đồng đã duyệt loại trừ Chủ nhật và ngày lễ khỏi laytime, còn thứ Bảy vẫn được tính.",en:"The approved charter party excludes Sundays and holidays from laytime, while Saturdays still count."}},{id:"DEMURRAGE",label:{vi:"Tiền phạt bốc dỡ chậm (USD)",en:"Demurrage due (USD)"},initial:"35700",expected:"18900",reference:"Bảng tính laytime",ref_value:{vi:"33.000 tấn ÷ 6.000 tấn/ngày; từ 08:00 thứ Năm đến 23:00 thứ Năm tuần sau; 16.800 USD/ngày",en:"33,000 t ÷ 6,000 t per day; from 08:00 Thursday to 23:00 the following Thursday; 16,800 USD per day"},hint:{vi:"Tính số giờ được phép, rồi trừ trọn ngày Chủ nhật khỏi thời gian đã dùng vì Chủ nhật rơi vào trong laytime.",en:"Work out the allowed hours, then deduct the whole Sunday from time used because it falls within laytime."}}],sop32:{vi:"Laytime cho phép = khối lượng ÷ mức xếp (ngày x 24 giờ); thời gian tính = thời gian thực tế trừ các khoảng loại trừ theo điều khoản; phạt = (giờ tính - giờ cho phép) ÷ 24 x mức phạt/ngày.",en:"Allowed laytime = quantity ÷ loading rate (days x 24 hours); time counted = elapsed time minus exceptions under the clause; demurrage = (hours counted - hours allowed) ÷ 24 x daily rate."},context:{label:"SOF / LT-5520",metrics:[{label:{vi:"Khối lượng hàng",en:"Cargo quantity"},value:"33,000 t"},{label:{vi:"Mức xếp",en:"Loading rate"},value:"6,000 t/day"},{label:{vi:"Mức phạt chậm",en:"Demurrage rate"},value:"16,800 USD/day"}]},crisis:{vi:"Người thuê tàu nhắn: “Anh sửa giúp SOF, ghi thêm 6 tiếng mưa ngừng xếp vào thứ Ba để giảm tiền phạt. Bên tôi sẽ ưu tiên ký thêm 3 chuyến và có phần cảm ơn riêng cho anh.”",en:"The charterer texts: “Please edit the SOF and add 6 hours of rain stoppage on Tuesday to cut the demurrage. We'll prioritise 3 more fixtures with you and there's a personal thank-you for you.”"},options:{safe:{vi:"Từ chối sửa SOF, dùng SOF đã được thuyền trưởng và đại lý ký, báo trưởng phòng về đề nghị; nếu cần thì thương lượng giảm phạt minh bạch bằng văn bản giữa hai công ty.",en:"Refuse to edit the SOF, use the SOF signed by the master and agent, report the offer to the head of department and, if needed, negotiate any reduction transparently in writing."},shortcut:{vi:"Thêm 6 giờ mưa vào SOF để giữ khách và nhận phần cảm ơn.",en:"Add 6 rain hours to the SOF to keep the client and take the thank-you."},wait:{vi:"Để yêu cầu đó lại, chờ người thuê tàu tự gửi bảng tính khác.",en:"Leave the request and wait for the charterer to send another calculation."}},questions:{vi:["Vì sao phải áp SHEX thay vì SHINC? Điều khoản nào chứng minh và nó làm thời gian tính thay đổi ra sao?","Trình bày cách tính tiền phạt bốc dỡ chậm và rủi ro pháp lý nếu chỉnh sửa SOF theo đề nghị của người thuê tàu."],en:["Why apply SHEX instead of SHINC? Which clause proves it and how does it change time counted?","Explain how you calculated demurrage and the legal risk of editing the SOF at the charterer's request."]},hints:{vi:["Đọc điều khoản laytime trong hợp đồng đã duyệt và đánh dấu những ngày được loại trừ.","Tính giờ cho phép và giờ đã dùng sau loại trừ theo SOP mục 3.2, rồi mới nhân mức phạt.","Đọc lại SOP mục 4.2: SOF là chứng từ gốc, không được sửa theo yêu cầu thương mại."],en:["Read the laytime clause in the approved charter party and mark the excepted days.","Compute allowed hours and hours used after exceptions per SOP 3.2 before applying the rate.","Re-read SOP 4.2: the SOF is a source document and must never be edited for commercial reasons."]}},learning:{summary:{vi:"Chuyên viên khai thác tàu và thuê tàu tìm hàng, chào tàu, đàm phán và chốt hợp đồng thuê chuyến, thuê định hạn, lập dự toán chuyến đi, chỉ định đại lý, theo dõi tàu tại cảng và tính laytime, demurrage, despatch. Nghề đòi hỏi am hiểu thị trường vận tải biển, điều khoản hợp đồng thuê tàu, vận đơn, luật hàng hải và giữ chứng từ trung thực để bảo vệ công ty khi phát sinh tranh chấp.",en:"A ship operations and chartering officer finds cargoes, offers tonnage, negotiates and fixes voyage and time charters, prepares voyage estimates, appoints agents, follows vessels in port and calculates laytime, demurrage and despatch. The role requires knowledge of shipping markets, charter party clauses, bills of lading and maritime law, and truthful documents that protect the company in disputes."},responsibilities:{vi:["Theo dõi thị trường, chào tàu, đàm phán điều khoản và chốt hợp đồng thuê tàu.","Lập dự toán chuyến đi: nhiên liệu, phí cảng, thời gian và lợi nhuận ngày tàu.","Chỉ định đại lý, gửi chỉ thị chuyến đi, theo dõi NOR, SOF và tiến độ làm hàng.","Tính laytime, demurrage, despatch và quyết toán cước với người thuê tàu.","Xử lý khiếu nại hàng hóa, tranh chấp hợp đồng và phối hợp với bảo hiểm P&I."],en:["Watch the market, offer tonnage, negotiate terms and fix charters.","Prepare voyage estimates: bunkers, port costs, time and daily earnings.","Appoint agents, issue voyage instructions and track NOR, SOF and cargo progress.","Calculate laytime, demurrage and despatch and settle freight with charterers.","Handle cargo claims and contract disputes and liaise with P&I insurers."]},competencies:[{name:{vi:"Đàm phán thuê tàu",en:"Charter negotiation"},desc:{vi:"Đàm phán cước, laytime, điều khoản loại trừ và trách nhiệm để cân bằng lợi ích và rủi ro.",en:"Negotiate freight, laytime, exceptions and liabilities to balance earnings and risk."}},{name:{vi:"Dự toán chuyến đi",en:"Voyage estimating"},desc:{vi:"Tính chi phí, thời gian, TCE và so sánh các phương án chuyến đi.",en:"Calculate costs, time and TCE and compare voyage options."}},{name:{vi:"Tính laytime & demurrage",en:"Laytime & demurrage"},desc:{vi:"Áp đúng điều khoản SHINC, SHEX, thời điểm bắt đầu và các khoảng loại trừ trong SOF.",en:"Apply SHINC or SHEX, the commencement time and SOF exceptions correctly."}},{name:{vi:"Quản lý chứng từ hàng hải",en:"Shipping documentation"},desc:{vi:"Kiểm soát NOR, SOF, vận đơn, biên bản hàng hóa đầy đủ, nhất quán và đúng thời hạn.",en:"Keep NOR, SOF, bills of lading and cargo reports complete, consistent and on time."}},{name:{vi:"Đạo đức thương mại",en:"Commercial ethics"},desc:{vi:"Không làm sai lệch chứng từ, không nhận lợi ích cá nhân, minh bạch khi thương lượng.",en:"Never falsify documents or take personal benefits and negotiate transparently."}}],knowledge:{vi:["Bộ luật Hàng hải Việt Nam 2015 về hợp đồng vận chuyển theo chuyến, thuê tàu định hạn và vận đơn.","Mẫu hợp đồng thuê chuyến tiêu chuẩn như GENCON và thuê định hạn như NYPE.","Định nghĩa laytime cho hợp đồng thuê tàu 2013: SHINC, SHEX, WWD, NOR và các thuật ngữ liên quan.","Quy tắc Hague-Visby về trách nhiệm của người vận chuyển theo vận đơn.","Nguyên tắc once on demurrage, always on demurrage và cách áp dụng khoảng loại trừ."],en:["Vietnam Maritime Code 2015 on voyage charters, time charters and bills of lading.","Standard voyage charter forms such as GENCON and time charter forms such as NYPE.","Laytime Definitions for Charter Parties 2013: SHINC, SHEX, WWD, NOR and related terms.","The Hague-Visby Rules on carrier liability under bills of lading.","The once on demurrage, always on demurrage principle and how exceptions apply."]},tools:["Phần mềm dự toán chuyến đi","Hệ thống theo dõi tàu AIS","Bảng tính laytime","Cơ sở dữ liệu khoảng cách cảng","Bản tin thị trường cước"],kpis:{vi:["Lợi nhuận ngày tàu (TCE) thực tế so với dự toán.","Tỷ lệ quyết toán demurrage trong 60 ngày sau khi kết thúc chuyến.","Số tranh chấp do sai sót chứng từ hoặc tính toán (mục tiêu bằng 0).","Thời gian tàu chờ cầu bình quân mỗi chuyến."],en:["Actual time charter equivalent (TCE) versus the estimate.","Share of demurrage claims settled within 60 days of voyage end.","Disputes caused by document or calculation errors (target zero).","Average berth waiting time per voyage."]},day:[{time:"08:00",vi:"Xem vị trí đội tàu, báo cáo trưa và tin thị trường cước.",en:"Check fleet positions, noon reports and freight market news."},{time:"09:30",vi:"Lập dự toán chuyến đi cho đơn chào hàng mới và đàm phán với môi giới.",en:"Prepare a voyage estimate for a new cargo offer and negotiate with brokers."},{time:"11:00",vi:"Gửi chỉ thị chuyến đi, kiểm tra NOR và kế hoạch làm hàng với đại lý.",en:"Send voyage instructions and check NOR and the cargo plan with the agent."},{time:"14:00",vi:"Tính laytime, demurrage theo SOF đã ký và gửi bảng tính cho người thuê.",en:"Calculate laytime and demurrage from the signed SOF and send it to the charterer."},{time:"16:30",vi:"Cập nhật lịch tàu, rủi ro thời tiết và báo cáo trưởng phòng.",en:"Update the vessel schedule and weather risks and report to the department head."}],mistakes:{vi:["Áp sai điều khoản loại trừ SHINC, SHEX khi tính laytime.","Bỏ qua nguyên tắc once on demurrage, always on demurrage hoặc xác định sai thời điểm bắt đầu laytime.","Chỉnh sửa SOF hoặc nhận lợi ích cá nhân để giảm phạt cho khách hàng."],en:["Applying the wrong SHINC or SHEX exceptions when counting laytime.","Ignoring once on demurrage, always on demurrage or setting the wrong laytime start.","Editing the SOF or accepting personal benefits to reduce a client's demurrage."]},career:[{vi:"Nhân viên khai thác tàu",en:"Operations assistant"},{vi:"Chuyên viên khai thác & thuê tàu",en:"Ship operations & chartering officer"},{vi:"Trưởng nhóm thuê tàu",en:"Chartering manager"},{vi:"Giám đốc thương mại hàng hải",en:"Commercial director, shipping"}],glossary:[{term:"Laytime",vi:"Thời gian làm hàng cho phép theo hợp đồng mà chủ tàu không thu thêm tiền.",en:"Time allowed in the charter for cargo work without extra payment to the owner."},{term:"Demurrage",vi:"Tiền phạt người thuê trả cho chủ tàu khi làm hàng vượt quá laytime.",en:"Money the charterer pays the owner when cargo work exceeds laytime."},{term:"NOR",vi:"Thông báo sẵn sàng làm hàng thuyền trưởng gửi khi tàu đã đến và sẵn sàng về mọi mặt.",en:"Notice of readiness from the master once the vessel has arrived and is ready in all respects."},{term:"SOF",vi:"Biên bản sự kiện ghi thời điểm đến, làm hàng, ngừng và hoàn thành, có chữ ký các bên.",en:"Statement of facts recording arrival, cargo work, stoppages and completion, signed by the parties."},{term:"SHEX",vi:"Chủ nhật và ngày lễ không tính vào laytime.",en:"Sundays and holidays excepted from laytime."}],quiz:[{q:{vi:"Hàng 24.000 tấn, mức xếp 8.000 tấn/ngày theo SHINC. Laytime cho phép là bao nhiêu giờ?",en:"Cargo of 24,000 t at 8,000 t per day SHINC. How many hours of laytime are allowed?"},options:{vi:["48 giờ","96 giờ","72 giờ","24 giờ"],en:["48 hours","96 hours","72 hours","24 hours"]},answer:2,explain:{vi:"24.000 ÷ 8.000 = 3 ngày = 72 giờ.",en:"24,000 ÷ 8,000 = 3 days = 72 hours."}},{q:{vi:"SHEX có nghĩa là gì?",en:"What does SHEX mean?"},options:{vi:["Chủ nhật và ngày lễ được loại trừ","Chủ nhật và ngày lễ vẫn tính","Thứ Bảy, Chủ nhật và ngày lễ được loại trừ","Chỉ tính ngày thời tiết tốt"],en:["Sundays and holidays excepted","Sundays and holidays included","Saturdays, Sundays and holidays excepted","Only good weather days count"]},answer:0,explain:{vi:"SHEX loại trừ Chủ nhật và ngày lễ; SHINC tính cả hai; SSHEX loại trừ thêm thứ Bảy.",en:"SHEX excludes Sundays and holidays; SHINC includes them; SSHEX also excludes Saturdays."}},{q:{vi:"Người thuê tàu nhờ sửa SOF để giảm phạt và hứa thêm hợp đồng. Bạn làm gì?",en:"A charterer asks you to edit the SOF to cut demurrage and promises more business. What do you do?"},options:{vi:["Sửa vì khách quan trọng","Sửa một nửa số giờ","Chờ khách gửi lại yêu cầu","Từ chối, dùng SOF đã ký và báo cáo trưởng phòng"],en:["Edit it because the client matters","Edit half the hours","Wait for the client to ask again","Refuse, use the signed SOF and report to the department head"]},answer:3,explain:{vi:"SOF là chứng từ gốc; làm sai lệch là gian lận và gây rủi ro pháp lý nghiêm trọng cho công ty.",en:"The SOF is a source document; falsifying it is fraud and creates serious legal risk."}},{q:{vi:"Theo nguyên tắc once on demurrage, always on demurrage, Chủ nhật rơi vào sau khi laytime đã hết thì sao?",en:"Under once on demurrage, always on demurrage, what happens to a Sunday after laytime has expired?"},options:{vi:["Được loại trừ như thường","Vẫn tính vào thời gian phạt chậm, trừ khi hợp đồng quy định khác","Tính gấp đôi","Hủy toàn bộ tiền phạt"],en:["Excepted as usual","Counts as demurrage time unless the charter says otherwise","Counts double","Cancels all demurrage"]},answer:1,explain:{vi:"Khi tàu đã vào thời gian phạt, các khoảng loại trừ của laytime thường không còn áp dụng.",en:"Once the vessel is on demurrage, laytime exceptions normally no longer apply."}}],tools_en:["Voyage estimation software","AIS vessel tracking system","Laytime calculation spreadsheet","Port distance database","Freight market reports"]}},"KK-992":{scenario:{company:"Công ty Đường sắt Đô thị Ánh Dương",supervisor:{name:"Lương Thị Kim Oanh",role:{vi:"Trưởng ca Trung tâm Điều độ",en:"OCC Shift Manager"}},ref_code:"OCC-1408",title:{vi:"Đúng chế độ lái. Đủ đoàn tàu. Không đánh đổi an toàn lấy giãn cách.",en:"Right driving mode. Enough trains. Never trade safety for headway."},brief:{vi:"Giờ cao điểm, tuyến số 2 (mô phỏng) cần giãn cách 4 phút. Thời gian chạy một chiều 28,5 phút, thời gian quay đầu tại mỗi ga cuối 4 phút. Đoàn tàu T09 mất liên lạc CBTC giữa ga S06 và S07, không còn cấp phép di chuyển từ hệ thống. Bản nháp lệnh điều độ OCC-1408 cho T09 chạy chế độ CM và tính 15 đoàn tàu vận doanh. Đối chiếu quy trình điều độ đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"At peak time, line 2 (training) needs a 4-minute headway. One-way running time is 28.5 minutes and turnback time at each terminus is 4 minutes. Train T09 has lost CBTC communication between stations S06 and S07 and no longer has a system movement authority. Draft dispatch order OCC-1408 sets T09 to CM mode and plans 15 trains in service. Compare it with the approved control procedure, correct both fields and write an evidence-based report."},reference_title:{vi:"Quy trình điều độ & biểu đồ chạy tàu đã duyệt · OCC-1408",en:"Approved control procedure & timetable · OCC-1408"},fields:[{id:"TRAIN_MODE",label:{vi:"Chế độ lái cho T09",en:"Driving mode for T09"},initial:"CM",expected:"RM",choices:["ATO","CM","RM"],reference:"Quy trình khi mất liên lạc CBTC",hint:{vi:"ATO và CM đều cần cấp phép di chuyển từ CBTC; khi mất liên lạc chỉ được chạy chế độ hạn chế tốc độ thấp theo lệnh điều độ.",en:"ATO and CM both need a CBTC movement authority; after a loss of communication only restricted low-speed mode under OCC authority is allowed."}},{id:"TRAINS_REQ",label:{vi:"Số đoàn tàu vận doanh cần (đoàn)",en:"Trains required in service"},initial:"15",expected:"17",reference:"Bảng lập biểu đồ chạy tàu",ref_value:{vi:"Giãn cách 4 phút; chạy một chiều 28,5 phút; quay đầu 4 phút tại mỗi ga cuối",en:"Headway 4 minutes; one-way running time 28.5 minutes; 4-minute turnback at each terminus"},hint:{vi:"Bản nháp chỉ tính thời gian chạy hai chiều, quên thời gian quay đầu ở hai ga cuối.",en:"The draft counted only running time both ways and forgot turnback time at both termini."}}],sop32:{vi:"Thời gian chu trình = 2 x thời gian chạy một chiều + 2 x thời gian quay đầu; số đoàn tàu vận doanh = chu trình ÷ giãn cách, làm tròn lên; chưa tính tàu dự phòng.",en:"Cycle time = 2 x one-way running time + 2 x turnback time; trains in service = cycle time ÷ headway, rounded up; spare trains not included."},context:{label:"OCC / OCC-1408",metrics:[{label:{vi:"Giãn cách mục tiêu",en:"Target headway"},value:"4 min"},{label:{vi:"Chạy một chiều",en:"One-way running time"},value:"28.5 min"},{label:{vi:"Quay đầu mỗi ga cuối",en:"Turnback per terminus"},value:"4 min"}]},crisis:{vi:"Phó giám đốc vận hành gọi: “Ke ga đang ùn khách, cho T09 cắt ATP chạy tay tốc độ thường cho nhanh. Còn trễ chuyến thì ghi dưới 5 phút thôi, khỏi phải báo cáo sự cố lên cơ quan quản lý.”",en:"The deputy operations director calls: “Platforms are overcrowded, let T09 cut out ATP and drive manually at normal speed. Log the delay as under 5 minutes so we don't have to report it to the regulator.”"},options:{safe:{vi:"Giữ T09 ở chế độ RM, giãn cách an toàn với tàu phía trước, thông báo hành khách, ghi đúng thời gian trễ và báo cáo sự cố theo quy trình, đề xuất tăng cường tàu khi CBTC phục hồi.",en:"Keep T09 in RM with safe spacing to the train ahead, inform passengers, record the true delay, report the incident per procedure and propose extra trains once CBTC recovers."},shortcut:{vi:"Cho T09 cắt ATP chạy tay tốc độ thường và ghi trễ dưới 5 phút.",en:"Let T09 cut out ATP at normal speed and log the delay as under 5 minutes."},wait:{vi:"Dừng mọi đoàn tàu, chờ hệ thống tự phục hồi và không thông báo gì.",en:"Hold all trains, wait for the system to recover and make no announcement."}},questions:{vi:["Vì sao T09 phải chạy chế độ RM chứ không phải CM? Điều kiện nào trong quy trình chứng minh?","Trình bày cách tính số đoàn tàu vận doanh và vì sao không được ghi giảm thời gian trễ."],en:["Why must T09 run in RM rather than CM? Which procedure condition proves it?","Explain how you calculated the trains in service and why the delay must not be under-reported."]},hints:{vi:["Kiểm tra T09 còn cấp phép di chuyển từ CBTC hay không, rồi đối chiếu bảng chế độ lái trong quy trình.","Tính thời gian chu trình đủ cả quay đầu theo SOP mục 3.2 rồi chia cho giãn cách, làm tròn lên.","Đọc lại SOP mục 4.2: không cắt thiết bị bảo vệ tàu và không sửa số liệu sự cố vì áp lực KPI."],en:["Check whether T09 still has a CBTC movement authority, then compare with the driving mode table.","Work out the full cycle including turnbacks per SOP 3.2, divide by the headway and round up.","Re-read SOP 4.2: never cut out train protection and never alter incident data for KPI reasons."]}},learning:{summary:{vi:"Chuyên viên điều độ đường sắt đô thị làm việc tại trung tâm điều độ (OCC), giám sát và điều hành chạy tàu theo biểu đồ, điều chỉnh giãn cách, xử lý sự cố tín hiệu, cửa chắn ke ga, cấp điện và tổ chức sơ tán hành khách. Nghề đòi hỏi hiểu hệ thống CBTC và các chế độ vận hành suy giảm, giao tiếp chuẩn qua vô tuyến và ra quyết định nhanh mà vẫn giữ nguyên tắc an toàn.",en:"An urban rail operations controller works in the operations control centre (OCC), supervising train service against the timetable, adjusting headways, handling signalling, platform screen door and power faults and organising passenger evacuation. The role requires knowledge of CBTC and degraded modes, standard radio communication and fast decisions that never compromise safety rules."},responsibilities:{vi:["Giám sát vị trí tàu, giãn cách và tình trạng hệ thống trên màn hình điều độ.","Điều chỉnh biểu đồ chạy tàu, bổ sung hoặc rút tàu khi nhu cầu thay đổi.","Cấp lệnh chạy tàu ở chế độ suy giảm khi tín hiệu, CBTC hoặc cửa chắn ke ga gặp sự cố.","Phối hợp điều độ điện, nhà ga, lái tàu và đội kỹ thuật khi xử lý sự cố.","Thông tin cho hành khách, ghi nhật ký điều độ và báo cáo sự cố đúng quy định."],en:["Monitor train positions, headways and system status on the control displays.","Adjust the timetable and insert or withdraw trains as demand changes.","Authorise degraded-mode operation when signalling, CBTC or platform screen doors fail.","Coordinate power control, stations, drivers and maintenance teams during incidents.","Inform passengers, keep the control log and report incidents as required."]},competencies:[{name:{vi:"Điều hành chạy tàu",en:"Train service control"},desc:{vi:"Giữ giãn cách đều, điều chỉnh thời gian dừng và xử lý tàu trễ để ổn định dịch vụ.",en:"Keep even headways, adjust dwell times and manage late trains to stabilise service."}},{name:{vi:"Vận hành suy giảm",en:"Degraded operations"},desc:{vi:"Áp dụng đúng chế độ lái, hạn chế tốc độ và quy tắc giãn cách khi hệ thống bị lỗi.",en:"Apply the correct driving mode, speed limits and spacing rules when systems fail."}},{name:{vi:"Giao tiếp an toàn",en:"Safety-critical communication"},desc:{vi:"Dùng mẫu câu chuẩn, nhắc lại và xác nhận lệnh qua vô tuyến để tránh hiểu nhầm.",en:"Use standard phrases, read-back and confirmation on the radio to avoid misunderstandings."}},{name:{vi:"Phân tích công suất tuyến",en:"Line capacity analysis"},desc:{vi:"Tính chu trình, số đoàn tàu và năng lực chuyên chở theo giãn cách mục tiêu.",en:"Calculate cycle time, fleet size and capacity for the target headway."}},{name:{vi:"Kỷ luật an toàn",en:"Safety discipline"},desc:{vi:"Không cắt thiết bị bảo vệ, không ghi sai số liệu và báo cáo đầy đủ mọi sự cố.",en:"Never bypass protection or falsify data and report every incident fully."}}],knowledge:{vi:["IEC 62290 về hệ thống quản lý và điều khiển vận tải đường ray đô thị, các cấp tự động hóa GoA0 đến GoA4.","IEEE 1474.1 về yêu cầu hiệu năng và chức năng của hệ thống CBTC.","Bộ tiêu chuẩn EN 50126, EN 50128, EN 50129 về RAMS và an toàn hệ thống tín hiệu đường sắt.","Pháp luật hiện hành về đường sắt và quy định khai thác đường sắt đô thị.","Cách tính thời gian chu trình, giãn cách, số đoàn tàu và năng lực chuyên chở giờ cao điểm."],en:["IEC 62290 on urban guided transport management and command systems and grades of automation GoA0 to GoA4.","IEEE 1474.1 on CBTC performance and functional requirements.","EN 50126, EN 50128 and EN 50129 on RAMS and railway signalling safety.","Current railway law and urban rail operating regulations.","Calculating cycle time, headway, fleet size and peak-hour capacity."]},tools:["Hệ thống giám sát tàu tự động (ATS)","Màn hình điều độ & sơ đồ tuyến","Hệ thống vô tuyến TETRA","Hệ thống SCADA cấp điện","Hệ thống thông tin hành khách (PIS)"],kpis:{vi:["Tỷ lệ chuyến tàu đúng giờ trong ngưỡng cho phép.","Mức tuân thủ giãn cách theo biểu đồ giờ cao điểm.","Thời gian khôi phục dịch vụ bình quân sau sự cố.","Số vi phạm quy trình an toàn trong điều độ (mục tiêu bằng 0)."],en:["Share of trips on time within the allowed tolerance.","Peak-hour headway adherence to the timetable.","Average service recovery time after incidents.","Safety procedure breaches in control operations (target zero)."]},day:[{time:"05:00",vi:"Nhận bàn giao ca, kiểm tra tình trạng hệ thống, tàu dự phòng và hạn chế tốc độ.",en:"Take the handover and check system status, spare trains and speed restrictions."},{time:"06:30",vi:"Điều hành giờ cao điểm sáng, theo dõi giãn cách và lưu lượng ke ga.",en:"Run the morning peak and monitor headways and platform crowding."},{time:"09:00",vi:"Rút bớt tàu về depot và phối hợp sửa chữa thiết bị ngoài giờ cao điểm.",en:"Withdraw trains to the depot and coordinate off-peak repairs."},{time:"11:30",vi:"Diễn tập tình huống mất liên lạc CBTC với lái tàu và nhà ga.",en:"Drill a CBTC communication loss with drivers and stations."},{time:"13:00",vi:"Ghi nhật ký điều độ, báo cáo sự kiện và bàn giao ca chiều.",en:"Complete the control log, report events and hand over to the afternoon shift."}],mistakes:{vi:["Cho tàu chạy chế độ CM hoặc cắt ATP khi không còn cấp phép di chuyển từ CBTC.","Lập biểu đồ quên thời gian quay đầu khiến thiếu tàu và giãn cách bị kéo dài.","Ghi giảm thời gian trễ hoặc không báo cáo sự cố để giữ chỉ số đúng giờ."],en:["Running a train in CM or cutting out ATP without a CBTC movement authority.","Planning without turnback time, leaving too few trains and longer headways.","Under-reporting delays or skipping incident reports to protect punctuality figures."]},career:[{vi:"Điều độ viên tập sự",en:"Trainee controller"},{vi:"Điều độ viên chạy tàu",en:"Train controller"},{vi:"Trưởng ca trung tâm điều độ",en:"OCC shift manager"},{vi:"Quản lý vận hành tuyến đường sắt đô thị",en:"Urban rail line operations manager"}],glossary:[{term:"CBTC",vi:"Hệ thống điều khiển tàu dựa trên truyền thông liên tục giữa tàu và thiết bị mặt đất.",en:"Communications-based train control using continuous train-to-wayside data links."},{term:"Headway",vi:"Giãn cách thời gian giữa hai đoàn tàu liên tiếp chạy cùng hướng.",en:"Time interval between two successive trains in the same direction."},{term:"RM",vi:"Chế độ lái tay hạn chế, tốc độ thấp, lái tàu tự quan sát đường, dùng khi mất cấp phép CBTC.",en:"Restricted manual mode at low speed on driver sight, used when CBTC authority is lost."},{term:"ATP",vi:"Bảo vệ tàu tự động, ngăn tàu vượt tốc độ hoặc vượt giới hạn cấp phép di chuyển.",en:"Automatic train protection that prevents overspeed and exceeding the movement authority."},{term:"Turnback",vi:"Thao tác đổi hướng chạy tàu tại ga cuối, gồm thời gian đổi buồng lái và kiểm tra.",en:"Reversing a train at a terminus, including cab change and checks."}],quiz:[{q:{vi:"Chạy một chiều 20 phút, quay đầu 5 phút tại mỗi ga cuối, giãn cách 5 phút. Cần bao nhiêu đoàn tàu vận doanh?",en:"One-way running time 20 minutes, 5-minute turnback at each terminus, 5-minute headway. How many trains are needed?"},options:{vi:["8 đoàn","10 đoàn","9 đoàn","12 đoàn"],en:["8 trains","10 trains","9 trains","12 trains"]},answer:1,explain:{vi:"Chu trình = 2 x 20 + 2 x 5 = 50 phút; 50 ÷ 5 = 10 đoàn tàu.",en:"Cycle = 2 x 20 + 2 x 5 = 50 minutes; 50 ÷ 5 = 10 trains."}},{q:{vi:"Khi đoàn tàu mất liên lạc CBTC, chế độ lái nào phù hợp?",en:"When a train loses CBTC communication, which driving mode is appropriate?"},options:{vi:["ATO","CM","Chạy tay tốc độ thường","RM theo lệnh điều độ"],en:["ATO","CM","Manual at normal speed","RM under OCC authority"]},answer:3,explain:{vi:"Không còn cấp phép di chuyển nên chỉ được chạy chế độ hạn chế, tốc độ thấp theo lệnh điều độ.",en:"Without a movement authority only restricted low-speed mode under OCC authority is allowed."}},{q:{vi:"Cấp trên yêu cầu cắt ATP để chạy nhanh và ghi giảm thời gian trễ. Bạn làm gì?",en:"A superior asks you to cut out ATP to run faster and under-report the delay. What do you do?"},options:{vi:["Từ chối, giữ chế độ an toàn, ghi đúng số liệu và báo cáo theo quy trình","Làm theo vì đang giờ cao điểm","Cắt ATP nhưng ghi đúng thời gian trễ","Không nghe máy để tránh trách nhiệm"],en:["Refuse, keep the safe mode, record true data and report per procedure","Comply because it is peak hour","Cut out ATP but log the true delay","Ignore the call to avoid responsibility"]},answer:0,explain:{vi:"Cắt thiết bị bảo vệ và làm sai lệch số liệu sự cố đều là vi phạm an toàn nghiêm trọng.",en:"Bypassing protection and falsifying incident data are both serious safety breaches."}},{q:{vi:"Cấp tự động hóa GoA4 theo IEC 62290 có nghĩa là gì?",en:"What does grade of automation GoA4 mean under IEC 62290?"},options:{vi:["Lái tay hoàn toàn","Có lái tàu giám sát ATO","Tự động hoàn toàn, không có nhân viên vận hành trên tàu","Chỉ có bảo vệ ATP"],en:["Fully manual driving","ATO with a driver supervising","Fully automatic with no staff on board","ATP protection only"]},answer:2,explain:{vi:"GoA4 là vận hành không người trên tàu (UTO), hệ thống tự xử lý cả tình huống bất thường.",en:"GoA4 is unattended train operation (UTO), with the system handling abnormal situations too."}}],tools_en:["Automatic train supervision (ATS) system","Control center displays & line diagrams","TETRA radio system","Power supply SCADA system","Passenger information system (PIS)"]}},"KK-993":{scenario:{company:"Trung tâm An ninh Hàng không Tân Hải",supervisor:{name:"Đinh Công Lâm",role:{vi:"Trưởng ca Soi chiếu An ninh",en:"Screening Shift Supervisor"}},ref_code:"SCR-3306",title:{vi:"Đúng quy định chất lỏng. Đúng điện năng pin. Mọi cảnh báo phải được giải quyết.",en:"Right liquids rule. Right battery rating. Every alarm resolved."},brief:{vi:"Tại điểm soi chiếu chuyến bay quốc tế, hành lý xách tay của một khách có chai mỹ phẩm dung tích 150 ml chỉ còn khoảng 60 ml và một sạc dự phòng ghi 27500 mAh, 3,6 V, không ghi Wh. Bản nháp phiếu xử lý SCR-3306 ghi chai mỹ phẩm ACCEPT và điện năng sạc 137.5 Wh (cần hãng chấp thuận). Đối chiếu quy trình soi chiếu đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"At an international departures checkpoint, a passenger's cabin bag holds a 150 ml cosmetic bottle with only about 60 ml left and a power bank labelled 27500 mAh, 3.6 V, with no Wh rating. Draft screening record SCR-3306 marks the bottle ACCEPT and the power bank at 137.5 Wh (airline approval needed). Compare it with the approved screening procedure, correct both fields and write an evidence-based report."},reference_title:{vi:"Quy trình soi chiếu & kiểm soát vật phẩm đã duyệt · SCR-3306",en:"Approved screening & prohibited items procedure · SCR-3306"},fields:[{id:"LAG_DECISION",label:{vi:"Quyết định với chai mỹ phẩm 150 ml",en:"Decision on the 150 ml cosmetic bottle"},initial:"ACCEPT",expected:"REJECT",choices:["ACCEPT","REJECT","EXEMPT"],reference:"Quy trình kiểm soát chất lỏng (LAGs)",hint:{vi:"Giới hạn 100 ml xét theo dung tích ghi trên vật chứa, không theo lượng còn bên trong; mỹ phẩm không thuộc diện miễn trừ.",en:"The 100 ml limit applies to the container capacity, not the amount left inside; cosmetics are not exempt."}},{id:"PB_WH",label:{vi:"Điện năng sạc dự phòng (Wh)",en:"Power bank energy rating (Wh)"},initial:"137.5",expected:"99",reference:"Phiếu kiểm tra pin lithium",ref_value:{vi:"Nhãn: 27500 mAh, điện áp danh định 3,6 V, không ghi Wh",en:"Label: 27500 mAh, nominal voltage 3.6 V, no Wh shown"},hint:{vi:"Bản nháp nhân với điện áp cổng USB 5 V; quy định dùng điện áp danh định của cell pin.",en:"The draft multiplied by the 5 V USB output; the rule uses the cell's nominal voltage."}}],sop32:{vi:"Điện năng (Wh) = dung lượng (mAh) x điện áp danh định (V) ÷ 1000. Pin dự phòng đến 100 Wh: mang xách tay; trên 100 đến 160 Wh: cần hãng chấp thuận; trên 160 Wh: cấm; không để trong hành lý ký gửi.",en:"Energy (Wh) = capacity (mAh) x nominal voltage (V) ÷ 1000. Spare batteries up to 100 Wh: cabin bag; over 100 to 160 Wh: airline approval needed; over 160 Wh: forbidden; never in checked baggage."},context:{label:"SCREENING / SCR-3306",metrics:[{label:{vi:"Dung tích chai",en:"Bottle capacity"},value:"150 ml"},{label:{vi:"Nhãn sạc dự phòng",en:"Power bank label"},value:"27500 mAh / 3.6 V"},{label:{vi:"Giới hạn chất lỏng",en:"Liquids limit"},value:"100 ml / 1 L bag"}]},crisis:{vi:"Máy phát hiện vết chất nổ (ETD) báo động trên quai túi của một khách khác. Trưởng nhóm nói: “Chắc do kem dưỡng tay thôi, hàng đang dài, khách lại là người quen của sếp, em cho qua luôn đi.”",en:"The explosive trace detector (ETD) alarms on another passenger's bag handle. The team lead says: “It's probably hand cream, the queue is long and he knows the boss, just clear him.”"},options:{safe:{vi:"Không cho qua khi cảnh báo chưa được giải quyết; lấy mẫu lại, lục soát trực quan theo quy trình, báo trưởng ca và đề nghị mở thêm làn để giảm ùn tắc.",en:"Do not clear an unresolved alarm; re-sample and hand search per procedure, inform the shift supervisor and request an extra lane to ease the queue."},shortcut:{vi:"Cho khách qua vì là người quen của lãnh đạo và hàng đang dài.",en:"Clear the passenger because he knows management and the queue is long."},wait:{vi:"Để túi sang một bên chưa xử lý và tiếp tục soi khách khác.",en:"Put the bag aside unresolved and keep screening other passengers."}},questions:{vi:["Vì sao chai 150 ml chỉ còn 60 ml vẫn phải REJECT? Quy định nào chứng minh và khách có những lựa chọn hợp lệ nào?","Trình bày cách tính điện năng sạc dự phòng và vì sao mọi cảnh báo ETD phải được giải quyết trước khi cho qua."],en:["Why must a 150 ml bottle with only 60 ml left still be REJECT? Which rule proves it and what valid options does the passenger have?","Explain how you calculated the power bank rating and why every ETD alarm must be resolved before clearance."]},hints:{vi:["Đọc dung tích in trên vật chứa và so với giới hạn trong quy trình kiểm soát chất lỏng.","Lấy dung lượng mAh và điện áp danh định trên nhãn rồi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không có ngoại lệ vì quan hệ cá nhân, cảnh báo chưa giải quyết thì không được cho qua."],en:["Read the capacity printed on the container and compare it with the liquids procedure limit.","Take the mAh capacity and nominal voltage from the label and apply the formula in SOP 3.2.","Re-read SOP 4.2: there are no exceptions for personal connections and an unresolved alarm is never cleared."]}},learning:{summary:{vi:"Chuyên viên soi chiếu an ninh hàng không kiểm tra hành khách, hành lý xách tay, hành lý ký gửi, hàng hóa và người, phương tiện vào khu vực hạn chế bằng máy soi tia X, cổng từ, thiết bị phát hiện vết chất nổ và lục soát trực quan, nhằm ngăn vật phẩm nguy hiểm lên tàu bay. Nghề đòi hỏi kỹ năng đọc ảnh soi, nắm chắc danh mục vật phẩm cấm và hạn chế, giao tiếp lịch sự nhưng kiên quyết và tuyệt đối không ngoại lệ.",en:"An aviation security screening officer screens passengers, cabin and hold baggage, cargo and people and vehicles entering restricted areas using X-ray, walk-through metal detectors, explosive trace detection and hand searches to keep dangerous items off aircraft. The role requires image interpretation skills, solid knowledge of prohibited and restricted items, courteous but firm communication and zero exceptions."},responsibilities:{vi:["Soi chiếu hành lý bằng máy tia X, đọc và phân tích ảnh để phát hiện vật phẩm nguy hiểm.","Kiểm tra hành khách qua cổng từ, máy soi toàn thân và lục soát trực quan khi có cảnh báo.","Áp dụng quy định chất lỏng (LAGs), pin lithium và hàng nguy hiểm trong hành lý.","Giải quyết mọi cảnh báo bằng thiết bị ETD, lục soát và báo cáo vật phẩm khả nghi.","Ghi sổ, lập biên bản tạm giữ vật phẩm và phối hợp lực lượng chức năng khi có tình huống."],en:["Screen baggage by X-ray and interpret images to detect dangerous items.","Screen passengers through metal detectors and body scanners and hand search on alarm.","Apply the liquids (LAGs), lithium battery and dangerous goods rules for baggage.","Resolve every alarm with ETD and searches and report suspicious items.","Keep logs, record surrendered items and coordinate with authorities when incidents arise."]},competencies:[{name:{vi:"Đọc ảnh soi tia X",en:"X-ray image interpretation"},desc:{vi:"Nhận diện vũ khí, chất nổ, linh kiện khả nghi qua hình dạng, màu vật liệu và mật độ.",en:"Recognise weapons, explosives and suspicious parts by shape, material colour and density."}},{name:{vi:"Lục soát trực quan",en:"Hand search"},desc:{vi:"Lục soát người và hành lý có hệ thống, tôn trọng hành khách và có người chứng kiến khi cần.",en:"Search people and bags systematically, respectfully and with a witness when required."}},{name:{vi:"Quy định vật phẩm nguy hiểm",en:"Dangerous items rules"},desc:{vi:"Áp đúng giới hạn chất lỏng, pin lithium, vật sắc nhọn và các trường hợp miễn trừ.",en:"Apply liquid, lithium battery and sharp item limits and the permitted exemptions."}},{name:{vi:"Giao tiếp với hành khách",en:"Passenger communication"},desc:{vi:"Giải thích quy định ngắn gọn, đưa ra lựa chọn hợp lệ và hạ nhiệt khi khách bức xúc.",en:"Explain rules briefly, offer valid options and calm upset passengers."}},{name:{vi:"Liêm chính & cảnh giác",en:"Integrity & vigilance"},desc:{vi:"Không ngoại lệ vì quen biết hay ùn tắc, giữ tập trung và báo cáo mọi áp lực bất thường.",en:"Make no exceptions for connections or queues, stay alert and report any undue pressure."}}],knowledge:{vi:["Phụ lục 17 Công ước Chicago (ICAO Annex 17) về an ninh hàng không.","Luật Hàng không dân dụng Việt Nam 2006 (sửa đổi, bổ sung 2014) và quy định về an ninh hàng không.","Quy định hạn chế chất lỏng, aerosol, gel (LAGs): vật chứa tối đa 100 ml trong túi nhựa trong suốt tối đa 1 lít.","Hướng dẫn kỹ thuật ICAO (Doc 9284) và quy định hàng nguy hiểm của IATA về pin lithium mang theo người.","Danh mục vật phẩm nguy hiểm cấm và hạn chế mang lên tàu bay do nhà chức trách hàng không công bố."],en:["ICAO Annex 17 on aviation security.","Vietnam Civil Aviation Law 2006 (amended 2014) and aviation security regulations.","Liquids, aerosols and gels (LAGs) rules: containers up to 100 ml in a clear bag of up to 1 litre.","ICAO Technical Instructions (Doc 9284) and IATA dangerous goods rules on passenger lithium batteries.","The list of prohibited and restricted items published by the aviation authority."]},tools:["Máy soi tia X đa góc","Cổng từ & máy dò kim loại cầm tay","Thiết bị phát hiện vết chất nổ (ETD)","Máy soi toàn thân","Hệ thống chiếu ảnh nguy hiểm giả lập (TIP)"],kpis:{vi:["Tỷ lệ phát hiện ảnh nguy hiểm giả lập (TIP) của từng nhân viên.","Tỷ lệ cảnh báo được giải quyết đúng quy trình (mục tiêu 100%).","Thời gian chờ soi chiếu bình quân của hành khách giờ cao điểm.","Số lần để lọt vật phẩm trong thử nghiệm an ninh bí mật (mục tiêu bằng 0)."],en:["Threat image projection (TIP) detection rate per officer.","Share of alarms resolved per procedure (target 100%).","Average passenger waiting time at peak hours.","Items missed in covert security tests (target zero)."]},day:[{time:"04:30",vi:"Nhận ca, kiểm tra thiết bị, thử máy soi và ETD theo danh mục đầu ca.",en:"Start the shift and test X-ray and ETD equipment against the opening checklist."},{time:"05:00",vi:"Soi chiếu cao điểm sáng, luân phiên vị trí đọc ảnh tối đa 20 phút mỗi lượt.",en:"Screen the morning peak, rotating off image reading every 20 minutes at most."},{time:"09:00",vi:"Giải quyết cảnh báo, lục soát túi và lập biên bản tạm giữ vật phẩm.",en:"Resolve alarms, search bags and record surrendered items."},{time:"11:00",vi:"Huấn luyện nhận dạng ảnh và xem kết quả TIP của ca.",en:"Do image recognition training and review the shift's TIP results."},{time:"12:30",vi:"Ghi sổ, bàn giao vật phẩm tạm giữ và báo cáo trưởng ca.",en:"Update the log, hand over surrendered items and report to the supervisor."}],mistakes:{vi:["Xét giới hạn 100 ml theo lượng chất lỏng còn lại thay vì dung tích vật chứa.","Tính điện năng pin bằng điện áp đầu ra 5 V thay vì điện áp danh định của cell.","Cho qua khi cảnh báo chưa được giải quyết vì ùn tắc hoặc vì quan hệ cá nhân."],en:["Judging the 100 ml limit by the amount left rather than the container capacity.","Calculating battery energy with the 5 V output instead of the cell's nominal voltage.","Clearing an unresolved alarm because of queues or personal connections."]},career:[{vi:"Nhân viên soi chiếu tập sự",en:"Trainee screening officer"},{vi:"Nhân viên soi chiếu an ninh hàng không",en:"Aviation security screening officer"},{vi:"Trưởng nhóm, trưởng ca soi chiếu",en:"Screening team lead, shift supervisor"},{vi:"Giám sát chất lượng an ninh hàng không",en:"Aviation security quality inspector"}],glossary:[{term:"LAGs",vi:"Chất lỏng, aerosol và gel bị giới hạn khi mang lên khoang khách chuyến bay quốc tế.",en:"Liquids, aerosols and gels restricted in cabin baggage on international flights."},{term:"ETD",vi:"Thiết bị phát hiện vết chất nổ bằng cách lấy mẫu bề mặt và phân tích.",en:"Explosive trace detection equipment that samples and analyses surfaces."},{term:"TIP",vi:"Hệ thống chèn ảnh vật nguy hiểm giả lập vào ảnh soi để đo và duy trì kỹ năng nhân viên.",en:"System that inserts fictional threat images into scans to measure and maintain skills."},{term:"Wh",vi:"Oát giờ, đơn vị điện năng của pin, bằng dung lượng (Ah) nhân điện áp danh định (V).",en:"Watt-hour, a battery energy unit equal to capacity (Ah) times nominal voltage (V)."},{term:"Alarm resolution",vi:"Quy trình xác định nguyên nhân cảnh báo và loại trừ mối đe dọa trước khi cho qua.",en:"The process of identifying an alarm's cause and ruling out a threat before clearance."}],quiz:[{q:{vi:"Sạc dự phòng 20000 mAh, điện áp danh định 3,7 V. Điện năng là bao nhiêu?",en:"A 20000 mAh power bank with a nominal voltage of 3.7 V. What is its energy rating?"},options:{vi:["100 Wh","74 Wh","20 Wh","370 Wh"],en:["100 Wh","74 Wh","20 Wh","370 Wh"]},answer:1,explain:{vi:"Điện năng = 20000 x 3,7 ÷ 1000 = 74 Wh, được mang xách tay.",en:"Energy = 20000 x 3.7 ÷ 1000 = 74 Wh, allowed in the cabin bag."}},{q:{vi:"Chai 200 ml chỉ còn 30 ml nước hoa trong hành lý xách tay chuyến quốc tế được xử lý thế nào?",en:"A 200 ml bottle with only 30 ml of perfume in a cabin bag on an international flight is handled how?"},options:{vi:["Cho qua vì còn ít","Cho qua nếu khách hứa không dùng","Không cho mang lên khoang khách","Đổ bớt ra rồi cho qua"],en:["Allow it since little is left","Allow it if the passenger promises not to use it","Not allowed in the cabin","Pour some out and allow it"]},answer:2,explain:{vi:"Giới hạn xét theo dung tích vật chứa; khách có thể gửi hành lý ký gửi hoặc bỏ lại.",en:"The limit is by container capacity; the passenger may check it in or surrender it."}},{q:{vi:"Máy ETD báo động, trưởng nhóm bảo cho qua vì khách quen lãnh đạo. Bạn làm gì?",en:"The ETD alarms and the team lead says to clear the passenger who knows management. What do you do?"},options:{vi:["Cho qua theo chỉ đạo","Cho qua nhưng ghi chú vào sổ","Hỏi khách có mang chất nổ không rồi cho qua","Giải quyết cảnh báo theo quy trình và báo trưởng ca"],en:["Clear him as instructed","Clear him but note it in the log","Ask if he carries explosives and clear him","Resolve the alarm per procedure and inform the shift supervisor"]},answer:3,explain:{vi:"Mọi cảnh báo phải được giải quyết trước khi cho qua; quan hệ cá nhân không phải lý do ngoại lệ.",en:"Every alarm must be resolved before clearance; personal connections are never grounds for exception."}},{q:{vi:"Sạc dự phòng 140 Wh của hành khách được xử lý ra sao?",en:"How is a passenger's 140 Wh power bank handled?"},options:{vi:["Mang xách tay khi có chấp thuận của hãng, tối đa 2 chiếc","Để trong hành lý ký gửi","Cấm hoàn toàn","Mang tự do không giới hạn"],en:["Cabin bag with airline approval, maximum 2 units","Packed in checked baggage","Completely forbidden","Carried freely without limits"]},answer:0,explain:{vi:"Pin dự phòng trên 100 đến 160 Wh chỉ mang xách tay khi được hãng chấp thuận, tối đa 2 chiếc mỗi khách.",en:"Spare batteries over 100 to 160 Wh go only in cabin bags with airline approval, at most 2 per passenger."}}],tools_en:["Multi-view X-ray screening machine","Walk-through & handheld metal detectors","Explosive trace detector (ETD)","Full-body scanner","Threat image projection system (TIP)"]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(16)})(window.KKR);
